    local function getTeamValue(player)
        local state = player:FindFirstChild("PlayerStates")
        if state and state:FindFirstChild("Team") then return state.Team.Value end
        return nil
    end
    
    local function isFriendly(player)
        local myTeam = getTeamValue(LocalPlayer)
        local otherTeam = getTeamValue(player)
        return myTeam ~= nil and myTeam == otherTeam
    end
    
    local function updateTarget()
        if not aimbotEnabled then cachedTarget = nil return end
        local closest, dist = nil, math.huge
        local camPos = Camera.CFrame.Position
        local camLook = Camera.CFrame.LookVector
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and not isFriendly(p) then
                local c = p.Character
                if c then
                    local part
if hitPartMode == "Random" then
    local parts = {
        "Head",
        "UpperTorso","LowerTorso",
        "LeftUpperArm","LeftLowerArm","LeftHand",
        "RightUpperArm","RightLowerArm","RightHand",
        "LeftUpperLeg","LeftLowerLeg","LeftFoot",
        "RightUpperLeg","RightLowerLeg","RightFoot"
    }
    for i = 1, 6 do
        local p = c:FindFirstChild(parts[math.random(#parts)])
        if p then part = p break end
    end
else
    part = c:FindFirstChild(hitPartName)
end
                    local hum = c:FindFirstChildOfClass("Humanoid")
                    if part and hum and hum.Health > 0 and not c:FindFirstChild("ForceField") then
                        local dir = part.Position - camPos
                        local mag = dir.Magnitude
                        local angle = math.deg(math.acos(camLook:Dot(dir.Unit)))
                        if angle <= (fovRadius/10) and mag < dist then
                            if wallCheckEnabled then
                                local rp = RaycastParams.new()
                                rp.FilterDescendantsInstances = {LocalPlayer.Character, c}
                                rp.FilterType = Enum.RaycastFilterType.Blacklist
                                if Workspace:Raycast(camPos, dir, rp) then continue end
                            end
                            dist, closest = mag, part
                        end
                    end
                end
            end
        end
        cachedTarget = closest
    end
    
    RunService.RenderStepped:Connect(updateTarget)
    local function updateStrongAimTarget()
    if not strongAimEnabled then
        strongAimTarget = nil
        return
    end

    local closest = nil
    local shortest = math.huge
    local camPos = Camera.CFrame.Position
    local camLook = Camera.CFrame.LookVector

    for _,plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer and not isFriendly(plr) then
            local char = plr.Character
            if char then
                local part
                if hitPartMode == "Random" then
                    local parts = {
                        "Head","UpperTorso","LowerTorso",
                        "LeftUpperArm","RightUpperArm",
                        "LeftUpperLeg","RightUpperLeg"
                    }
                    for i = 1,5 do
                        local p = char:FindFirstChild(parts[math.random(#parts)])
                        if p then part = p break end
                    end
                else
                    part = char:FindFirstChild(hitPartName)
                end

                local hum = char:FindFirstChildOfClass("Humanoid")
                if part and hum and hum.Health > 0 then
                    local dir = part.Position - camPos
                    local angle = math.deg(math.acos(camLook:Dot(dir.Unit)))

                    if angle <= (aimFovRadius / 10) then
                        local dist = dir.Magnitude
                        if dist < shortest then
                            shortest = dist
                            closest = part
                        end
                    end
                end
            end
        end
    end

    strongAimTarget = closest
end
RunService.RenderStepped:Connect(function()
    updateStrongAimTarget()

    AimFOV.Visible = strongAimEnabled
    AimFOV.Radius = aimFovRadius
    AimFOV.Position = Vector2.new(Camera.ViewportSize.X/2, Camera.ViewportSize.Y/2)

    if strongAimEnabled and strongAimTarget then
        Camera.CFrame = CFrame.new(
            Camera.CFrame.Position,
            strongAimTarget.Position
        )
    end
end)
    local old
    old = hookmetamethod(game, "__namecall", function(self, ...)
        local m = getnamecallmethod()
        if not checkcaller() and self == Workspace and (m == "Raycast" or m == "FindPartOnRay") then
            local target = cachedTarget
            if target and math.random(1,100) <= hitChance then
                local args = {...}
                local origin, direction
                if m == "Raycast" then origin, direction = args[1], args[2]
                else local r = args[1] if typeof(r) == "Ray" then origin, direction = r.Origin, r.Direction end end
                if origin and direction then
                    return {Instance = target, Position = target.Position, Normal = (target.Position - origin).Unit, Material = Enum.Material.Plastic}
                end
            end
        end
        return old(self, ...)
    end)
    
