    local espEnabled, hpESPEnabled, playerDistanceEspEnabled = false, false, false
    local espConnections, hpESPConnections, playerDistanceLabels = {}, {}, {}
    local updateConnection
    
    local function updateESPColor(player)
        if player.Character then
            local esp = player.Character:FindFirstChild("PlayerESP")
            if esp then
                esp.FillColor = isFriendly(player) and Color3.fromRGB(0,255,0) or Color3.fromRGB(255,0,0)
                esp.OutlineColor = esp.FillColor
            end
            local root = player.Character:FindFirstChild("HumanoidRootPart")
            if root then
                local hp = root:FindFirstChild("HpESP")
                if hp and hp:FindFirstChildOfClass("TextLabel") then
                    hp:FindFirstChildOfClass("TextLabel").TextColor3 = isFriendly(player) and Color3.fromRGB(0,255,0) or Color3.fromRGB(255,0,0)
                end
                local dist = root:FindFirstChild("DistanceESP")
                if dist and dist:FindFirstChildOfClass("TextLabel") then
                    dist:FindFirstChildOfClass("TextLabel").TextColor3 = isFriendly(player) and Color3.fromRGB(0,255,0) or Color3.fromRGB(255,0,0)
                end
            end
        end
    end
    
    local function createESP(player)
        if player == LocalPlayer then return end
        local function addESP(character)
            if character:FindFirstChild("PlayerESP") then return end
            local root = character:FindFirstChild("HumanoidRootPart")
            if not root then return end
            local highlight = Instance.new("Highlight")
            highlight.Name = "PlayerESP"
            highlight.Adornee = character
            highlight.FillColor = isFriendly(player) and Color3.fromRGB(0,255,0) or Color3.fromRGB(255,0,0)
            highlight.OutlineColor = highlight.FillColor
            highlight.FillTransparency, highlight.OutlineTransparency, highlight.Parent = 0.6, 0, character
        end
        if player.Character then addESP(player.Character) end
        espConnections[player] = player.CharacterAdded:Connect(function(char)
            repeat task.wait() until char:FindFirstChild("HumanoidRootPart")
            addESP(char)
            updateESPColor(player)
        end)
    end
    
    local function removeESP()
        for _, player in ipairs(Players:GetPlayers()) do
            if player.Character and player.Character:FindFirstChild("PlayerESP") then player.Character.PlayerESP:Destroy() end
        end
    end
    
    local function createHPEsp(player)
        if player == LocalPlayer then return end
        local function addBillboard(character)
            local humanoid = character:FindFirstChildOfClass("Humanoid")
            local root = character:FindFirstChild("HumanoidRootPart")
            if not humanoid or not root or root:FindFirstChild("HpESP") then return end
            local billboard = Instance.new("BillboardGui")
            billboard.Name, billboard.AlwaysOnTop, billboard.Size, billboard.StudsOffset, billboard.Parent = "HpESP", true, UDim2.new(0,200,0,25), Vector3.new(0,-15,0), root
            local hpLabel = Instance.new("TextLabel")
            hpLabel.BackgroundTransparency, hpLabel.Size, hpLabel.TextColor3, hpLabel.TextSize, hpLabel.Font, hpLabel.Text, hpLabel.Parent = 1, UDim2.new(1,0,1,0), (isFriendly(player) and Color3.fromRGB(0,255,0) or Color3.fromRGB(255,0,0)), 13, Enum.Font.SourceSansBold, "HP:"..math.floor(humanoid.Health), billboard
            humanoid.HealthChanged:Connect(function() if hpLabel then hpLabel.Text = "HP:"..math.floor(humanoid.Health) end end)
        end
        if player.Character then addBillboard(player.Character) end
        hpESPConnections[player] = player.CharacterAdded:Connect(function(char)
            repeat task.wait() until char:FindFirstChild("HumanoidRootPart") and char:FindFirstChildOfClass("Humanoid")
            addBillboard(char)
            updateESPColor(player)
        end)
    end
    
    local function removeHPEsp()
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and player.Character then
                local root = player.Character:FindFirstChild("HumanoidRootPart")
                if root and root:FindFirstChild("HpESP") then root.HpESP:Destroy() end
            end
        end
    end
    
    local function createPlayerDistanceEsp(player)
        if not player.Character then return end
        local head = player.Character:FindFirstChild("Head")
        if not head or head:FindFirstChild("DistanceESP") then return end
        local billboard = Instance.new("BillboardGui")
        billboard.Name, billboard.AlwaysOnTop, billboard.Size, billboard.StudsOffset, billboard.Parent = "DistanceESP", true, UDim2.new(0,200,0,25), Vector3.new(0,15,0), head
        local distanceLabel = Instance.new("TextLabel")
        distanceLabel.BackgroundTransparency, distanceLabel.Size, distanceLabel.TextColor3, distanceLabel.TextSize, distanceLabel.Font, distanceLabel.Parent = 1, UDim2.new(1,0,1,0), (isFriendly(player) and Color3.fromRGB(0,255,0) or Color3.fromRGB(255,0,0)), 13, Enum.Font.SourceSansBold, billboard
        playerDistanceLabels[player] = distanceLabel
    end
    
    local function updatePlayerDistanceEsp()
        local localChar = LocalPlayer.Character
        if not localChar or not localChar:FindFirstChild("HumanoidRootPart") then return end
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
                createPlayerDistanceEsp(player)
                local distance = (localChar.HumanoidRootPart.Position - player.Character.HumanoidRootPart.Position).Magnitude
                if playerDistanceLabels[player] then playerDistanceLabels[player].Text = "stun:"..math.floor(distance) end
                updateESPColor(player)
            end
        end
    end

    CreateToggle("玩家透视/esp player", false, function(state)
        espEnabled = state
        if state then
            for _, p in ipairs(Players:GetPlayers()) do createESP(p) end
            espConnections["PlayerAdded"] = Players.PlayerAdded:Connect(createESP)
        else
            removeESP()
            for _, c in pairs(espConnections) do pcall(function() c:Disconnect() end) end
            espConnections = {}
        end
    end)
    
    CreateToggle("血量透视/esp hp", false, function(state)
        hpESPEnabled = state
        if state then
            for _, p in ipairs(Players:GetPlayers()) do createHPEsp(p) end
            hpESPConnections["PlayerAdded"] = Players.PlayerAdded:Connect(createHPEsp)
        else
            removeHPEsp()
            for _, c in pairs(hpESPConnections) do pcall(function() c:Disconnect() end) end
            hpESPConnections = {}
        end
    end)
    
    CreateToggle("距离透视/esp distance", false, function(state)
        playerDistanceEspEnabled = state
        if state then
            updateConnection = RunService.RenderStepped:Connect(updatePlayerDistanceEsp)
        else
            if updateConnection then updateConnection:Disconnect() end
            for player, label in pairs(playerDistanceLabels) do if label.Parent then label.Parent:Destroy() end end
            playerDistanceLabels = {}
        end
    end)
    
    local Weapons = ReplicatedStorage:FindFirstChild("Import") and ReplicatedStorage.Import:FindFirstChild("Assets") and ReplicatedStorage.Import.Assets:FindFirstChild("Weapons")
    local cache = {}
    CreateToggle("快速切枪/fast equip", false, function(state)
        if not Weapons then return end
        if state then
            for _,d in ipairs(Weapons:GetDescendants()) do
                if d.Name == "EquipTime" and d:IsA("ValueBase") then cache[d] = d.Value d.Value = 0 end
            end
        else
            for d,v in pairs(cache) do if d and d.Parent then d.Value = v end end
        end
    end)
end

