    frameCount = frameCount + 1
end)

task.spawn(function()
    while true do
        local now = tick()
        local deltaTime = now - lastTime
        
        if deltaTime >= 0.5 then
            local fps = math.floor(frameCount / deltaTime)
            frameCount = 0
            lastTime = now

            local displayColor = "rgb(255,255,255)"
            local displayIcon = "signal"

            if fps >= 60 then
                displayColor = "rgb(0,255,0)"
                displayIcon = "signal"
            elseif fps >= 30 then
                displayColor = "rgb(255,255,0)"
                displayIcon = "signal-high"
            else
                displayColor = "rgb(255,0,0)"
                displayIcon = "signal-medium"
            end

            pcall(function()
                FPSTag.Icon = displayIcon
                FPSTag:SetIcon(displayIcon)
            end)

            FPSTag:SetTitle(string.format('<font color="%s">%d FPS</font>', displayColor, fps))
        end
        task.wait(0.1)
    end
end)

