local RespawnEvent = ReplicatedStorage:WaitForChild("Events"):WaitForChild("Player"):WaitForChild("ChangePlayerMode")
local InteractEvent = ReplicatedStorage:WaitForChild("Events"):WaitForChild("Character"):WaitForChild("Interact")

local function applyHighlight(parent, outlineColor)
    if parent:FindFirstChild("_KanlHL") then return end
    local hl = Instance.new("Highlight")
    hl.Name = "_KanlHL"
    hl.FillTransparency = 1
    hl.OutlineTransparency = 0
    hl.OutlineColor = outlineColor
    hl.FillColor = outlineColor
    hl.Adornee = parent
    hl.Parent = parent
end

local function applyPlayerEsp(plr)
    if plr == LocalPlayer then return end
    local function onChar(char)
        if G.PlayerEspOn then applyHighlight(char, Color3.fromRGB(0, 255, 0)) end
    end
    if plr.Character then onChar(plr.Character) end
    plr.CharacterAdded:Connect(onChar)
end

local function setCharacterCollision(character, state)
    for _, v in ipairs(character:GetDescendants()) do
        if v:IsA("BasePart") then
            v.CanCollide = state
        end
    end
end

local function enableNoclip()
    local character = LocalPlayer.Character
    if not character then return end
    setCharacterCollision(character, false)
    if G.NoclipConnection then G.NoclipConnection:Disconnect() end
    G.NoclipConnection = RunService.Stepped:Connect(function()
        if not G.NoclipEnabled then return end
        local char = LocalPlayer.Character
        if char then
            for _, v in ipairs(char:GetDescendants()) do
                if v:IsA("BasePart") then
                    v.CanCollide = false
                end
            end
        end
    end)
end

local function disableNoclip()
    if G.NoclipConnection then
        G.NoclipConnection:Disconnect()
        G.NoclipConnection = nil
    end
    local character = LocalPlayer.Character
    if character then setCharacterCollision(character, true) end
end

local function checkOnGround(character)
    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = {character}
    local result = workspace:Raycast(root.Position, Vector3.new(0, -3.5, 0), params)
    return result ~= nil
end

local function createFlyMenu()
    local ScreenGui = Instance.new("ScreenGui")
    local MainFrame = Instance.new("Frame")
