    Title = "local mods",
    Icon = "sport-shoe",
    Locked = false,
})

local Tabauto = Window:Tab({
    Title = "automation",
    Icon = "tractor",
    Locked = false,
})

local G = {}
G.AutoRespawn = false
G.AutoRevive = false
G.AutoCarry = false
G.ReviveRange = 20
G.TpWalking = false
G.TpWalkSpeed = 5
G.NoclipEnabled = false
G.NoclipConnection = nil
G.BhopEnabled = false
G.BhopJumpDelay = 0
G.BhopLastGroundTime = 0
G.BhopOnGround = false
G.PlayerEspOn = false
G.UpKey = "K"
G.DownKey = "L"
G.FlySpeed = 1.5
G.LoopCamera = false

local RespawnEvent = ReplicatedStorage:WaitForChild("Events"):WaitForChild("Player"):WaitForChild("ChangePlayerMode")
local InteractEvent = ReplicatedStorage:WaitForChild("Events"):WaitForChild("Character"):WaitForChild("Interact")

local function applyHighlight(parent, outlineColor)
    if parent:FindFirstChild("_KanlHL") then return end
    local hl = Instance.new("Highlight")
    hl.Name = "_KanlHL"
    hl.FillTransparency = 1
    hl.OutlineTransparency = 0
    hl.OutlineColor = outlineColor
    hl.FillColor = outlineColor
    hl.Adornee = parent
    hl.Parent = parent
end

local function applyPlayerEsp(plr)
    if plr == LocalPlayer then return end
    local function onChar(char)
        if G.PlayerEspOn then applyHighlight(char, Color3.fromRGB(0, 255, 0)) end
    end
    if plr.Character then onChar(plr.Character) end
    plr.CharacterAdded:Connect(onChar)
end

local function setCharacterCollision(character, state)
    for _, v in ipairs(character:GetDescendants()) do
        if v:IsA("BasePart") then
            v.CanCollide = state
        end
    end
end

local function enableNoclip()
    local character = LocalPlayer.Character
    if not character then return end
    setCharacterCollision(character, false)
    if G.NoclipConnection then G.NoclipConnection:Disconnect() end
    G.NoclipConnection = RunService.Stepped:Connect(function()
        if not G.NoclipEnabled then return end
        local char = LocalPlayer.Character
        if char then
            for _, v in ipairs(char:GetDescendants()) do
                if v:IsA("BasePart") then
                    v.CanCollide = false
                end
            end
        end
    end)
end

local function disableNoclip()
    if G.NoclipConnection then
        G.NoclipConnection:Disconnect()
        G.NoclipConnection = nil
    end
    local character = LocalPlayer.Character
    if character then setCharacterCollision(character, true) end
end

local function checkOnGround(character)
    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = {character}
    local result = workspace:Raycast(root.Position, Vector3.new(0, -3.5, 0), params)
    return result ~= nil
end

local function createFlyMenu()
    local ScreenGui = Instance.new("ScreenGui")
    local MainFrame = Instance.new("Frame")
    local Title = Instance.new("TextLabel")
    local CloseBtn = Instance.new("TextButton")
    local MinBtn = Instance.new("TextButton")
    local UpBtn = Instance.new("TextButton")
    local DownBtn = Instance.new("TextButton")

    ScreenGui.Name = "MovementTool"
    ScreenGui.Parent = LocalPlayer:WaitForChild("PlayerGui")
    ScreenGui.ResetOnSpawn = false

    MainFrame.Name = "MainFrame"
    MainFrame.Parent = ScreenGui
    MainFrame.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
    MainFrame.BorderSizePixel = 0
    MainFrame.Position = UDim2.new(0.5, -40, 0.5, -50)
    MainFrame.Size = UDim2.new(0, 80, 0, 100)
    MainFrame.Active = true
    MainFrame.Draggable = true

    Title.Size = UDim2.new(1, -30, 0, 20)
    Title.BackgroundTransparency = 1
    Title.Text = "Move"
    Title.TextColor3 = Color3.fromRGB(255, 255, 255)
    Title.TextSize = 10
    Title.Parent = MainFrame

    MinBtn.Size = UDim2.new(0, 15, 0, 15)
    MinBtn.Position = UDim2.new(1, -30, 0, 2)
    MinBtn.Text = "-"
    MinBtn.Parent = MainFrame
    MinBtn.AutoButtonColor = false

    CloseBtn.Size = UDim2.new(0, 15, 0, 15)
    CloseBtn.Position = UDim2.new(1, -15, 0, 2)
    CloseBtn.Text = "X"
    CloseBtn.Parent = MainFrame
    CloseBtn.AutoButtonColor = false

    UpBtn.Size = UDim2.new(0, 60, 0, 30)
    UpBtn.Position = UDim2.new(0, 10, 0, 25)
    UpBtn.Text = "▲"
    UpBtn.Parent = MainFrame
    UpBtn.AutoButtonColor = false

    DownBtn.Size = UDim2.new(0, 60, 0, 30)
    DownBtn.Position = UDim2.new(0, 10, 0, 60)
    DownBtn.Text = "▼"
    DownBtn.Parent = MainFrame
    DownBtn.AutoButtonColor = false

    local isMin = false
    MinBtn.MouseButton1Click:Connect(function()
        isMin = not isMin
        MainFrame.Size = isMin and UDim2.new(0, 80, 0, 20) or UDim2.new(0, 80, 0, 100)
        UpBtn.Visible = not isMin
        DownBtn.Visible = not isMin
    end)

    CloseBtn.MouseButton1Click:Connect(function()
        ScreenGui:Destroy()
    end)

    local upPress = false
    local downPress = false

    UpBtn.MouseButton1Down:Connect(function() upPress = true end)
    UpBtn.MouseButton1Up:Connect(function() upPress = false end)
    UpBtn.TouchLongPress:Connect(function() upPress = true end)

    DownBtn.MouseButton1Down:Connect(function() downPress = true end)
    DownBtn.MouseButton1Up:Connect(function() downPress = false end)
    DownBtn.TouchLongPress:Connect(function() downPress = true end)

    RunService.Heartbeat:Connect(function()
        local char = LocalPlayer.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if root then
            local isUpHeld = upPress or UserInputService:IsKeyDown(Enum.KeyCode[G.UpKey:upper()])
            local isDownHeld = downPress or UserInputService:IsKeyDown(Enum.KeyCode[G.DownKey:upper()])
            if isUpHeld then root.CFrame = root.CFrame * CFrame.new(0, G.FlySpeed, 0) end
            if isDownHeld then root.CFrame = root.CFrame * CFrame.new(0, -G.FlySpeed, 0) end
        end
    end)
end

LocalPlayer.CharacterAdded:Connect(function()
    if G.NoclipEnabled then
        task.wait(0.2)
        enableNoclip()
    end
end)

RunService.Heartbeat:Connect(function()
    if G.AutoRespawn then
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum and hum.Health <= 0 then
            RespawnEvent:FireServer(true)
        end
    end
end)

RunService.Heartbeat:Connect(function()
    if not (G.AutoRevive or G.AutoCarry) then return end
    local myChar = LocalPlayer.Character
    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myRoot then return end
    for _, player in pairs(Players:GetPlayers()) do
        if player ~= LocalPlayer and player.Character then
            local targetRoot = player.Character:FindFirstChild("HumanoidRootPart")
            if targetRoot then
                local dist = (myRoot.Position - targetRoot.Position).Magnitude
                if dist <= G.ReviveRange then
                    if G.AutoRevive then InteractEvent:FireServer("Revive", true, player.Name) end
                    if G.AutoCarry then InteractEvent:FireServer("Carry", nil, player.Name) end
                end
            end
        end
    end
end)

RunService.Heartbeat:Connect(function()
    if not G.TpWalking then return end
    local chr = LocalPlayer.Character
    if not chr then return end
    local hrp = chr:FindFirstChild("HumanoidRootPart")
    local hum = chr:FindFirstChildWhichIsA("Humanoid")
    local delta = RunService.Heartbeat:Wait()
    if hrp and hum and hum.MoveDirection.Magnitude > 0 then
        hrp.CFrame = hrp.CFrame + (hum.MoveDirection * G.TpWalkSpeed * delta)
    end
end)

RunService.Heartbeat:Connect(function()
    if not G.BhopEnabled then return end
    local character = LocalPlayer.Character
    if not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid or humanoid.Health <= 0 then return end
    local isMobile = UserInputService.TouchEnabled
    local currentlyOnGround = checkOnGround(character)
    if currentlyOnGround then
        if not G.BhopOnGround then
            G.BhopOnGround = true
            G.BhopLastGroundTime = tick()
        end
        if tick() - G.BhopLastGroundTime >= G.BhopJumpDelay then
            local shouldTrigger = isMobile or UserInputService:IsKeyDown(Enum.KeyCode.Space)
            if shouldTrigger then
                humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
            end
        end
    else
        G.BhopOnGround = false
    end
end)

