    Callback = function(state)
        _G.InstantReload = state
        
        local function apply()
            if not _G.InstantReload then return end
            for _, v in pairs(getgc(true)) do
                if type(v) == "table" then
                    if rawget(v, "MagCapacity") and rawget(v, "ReloadSpeed") then
                        rawset(v, "ReloadSpeed", 0)
                        rawset(v, "InsertTime", 0)
                        rawset(v, "ReloadTime", 0)
                    end
                end
            end
        end

        if state then
            local player = game:GetService("Players").LocalPlayer
            local function listen(char)
                char.ChildAdded:Connect(function(child)
                    if _G.InstantReload and child:IsA("Tool") then
                        task.spawn(function()
                            for i = 1, 15 do
                                if not _G.InstantReload then break end
                                apply()
                                task.wait(0.2)
                            end
                        end)
                    end
                end)
            end

            if player.Character then listen(player.Character) end
            player.CharacterAdded:Connect(listen)
            apply()
        end
    end
})
local ToggleState = false
local cachedTargets = {}
local lastScan = 0

local function scanGC()
	local now = tick()
	if now - lastScan < 5 then return end
	lastScan = now
	table.clear(cachedTargets)
	local key = "RoundsPerMinute"
	for _, v in pairs(getgc(true)) do
		if type(v) == "table" and rawget(v, key) then
			table.insert(cachedTargets, v)
		end
	end
end

task.spawn(function()
	while task.wait(0.1) do
		if ToggleState then
			scanGC()
			local inf = math.huge
			for i = 1, #cachedTargets do
				local v = cachedTargets[i]
				if type(v) == "table" then
					rawset(v, "RoundsPerMinute", inf)
				end
			end
		end
	end
end)

