		ToggleState = state
		if state then
			lastScan = 0
			scanGC()
		end
	end
})
local espTab = Window:Tab({  
    Title = "esp",  
    Icon = "eye",  
    Locked = false,
})
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LocalPlayer = Players.LocalPlayer
local Camera = game:GetService("Workspace").CurrentCamera

local ESPFolder = Instance.new("Folder")
ESPFolder.Name = "TeamESP"
ESPFolder.Parent = game.CoreGui

local ESPObjects = {}
_G.TeamESPActive = false
_G.HealthESPActive = false

local function getESPColor(targetPlayer)
    local char = targetPlayer.Character
    if char then
        local unit = char:FindFirstChild("Unit")
        if unit and unit.Value == "Civilian" then
            return Color3.fromRGB(255, 127, 0)
        end
    end

    if not LocalPlayer.Team or not targetPlayer.Team then 
        return Color3.fromRGB(255, 255, 255) 
    end
    if targetPlayer.Team == LocalPlayer.Team then
        return Color3.fromRGB(0, 255, 0)
    else
        return Color3.fromRGB(255, 0, 0)
    end
end

local function removeESP(player)
    if ESPObjects[player] then
        if ESPObjects[player].highlight then ESPObjects[player].highlight:Destroy() end
        if ESPObjects[player].healthBg then ESPObjects[player].healthBg:Destroy() end
        if ESPObjects[player].healthBar then ESPObjects[player].healthBar:Destroy() end
        if ESPObjects[player].render then ESPObjects[player].render:Disconnect() end
        ESPObjects[player] = nil
    end
end

local function createESP(player)
    if player == LocalPlayer then return end
    removeESP(player)

    local objects = {
        highlight = nil,
        healthBg = nil,
        healthBar = nil
    }

    if _G.TeamESPActive then
        local highlight = Instance.new("Highlight")
        highlight.FillTransparency = 0.5
        highlight.OutlineTransparency = 0
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.Adornee = player.Character
        highlight.Parent = ESPFolder
        objects.highlight = highlight
    end

    if _G.HealthESPActive then
        local healthBg = Drawing.new("Line")
        healthBg.Visible = false
        healthBg.Color = Color3.fromRGB(0, 0, 0)
        healthBg.Thickness = 5 
        healthBg.Transparency = 0.8

        local healthBar = Drawing.new("Line")
        healthBar.Visible = false
        healthBar.Thickness = 3 
        healthBar.Transparency = 1

        objects.healthBg = healthBg
        objects.healthBar = healthBar
    end

    objects.render = RunService.RenderStepped:Connect(function()
        local char = player.Character
        if char and char:FindFirstChild("HumanoidRootPart") and char:FindFirstChild("Humanoid") then
            local rootPart = char.HumanoidRootPart
            local hum = char.Humanoid
            local pos, onScreen = Camera:WorldToViewportPoint(rootPart.Position)

            if onScreen then
                if _G.TeamESPActive and objects.highlight then
                    local color = getESPColor(player)
                    objects.highlight.Adornee = char
                    objects.highlight.FillColor = color
                    objects.highlight.OutlineColor = color
                end

                if _G.HealthESPActive and objects.healthBar then
                    local top = Camera:WorldToViewportPoint(rootPart.Position + Vector3.new(0, 3, 0))
                    local bottom = Camera:WorldToViewportPoint(rootPart.Position - Vector3.new(0, 3, 0))
                    local barHeight = top.Y - bottom.Y
                    local barPos = Vector2.new(pos.X - (math.abs(barHeight) / 4) - 6, pos.Y)
                    
                    local healthPercent = math.clamp(hum.Health / hum.MaxHealth, 0, 1)
                    local barColor = Color3.fromRGB(255, 0, 0):Lerp(Color3.fromRGB(0, 255, 0), healthPercent)
                    
                    objects.healthBg.From = Vector2.new(barPos.X, pos.Y - barHeight / 2)
                    objects.healthBg.To = Vector2.new(barPos.X, pos.Y + barHeight / 2)
                    objects.healthBg.Visible = true

                    objects.healthBar.From = Vector2.new(barPos.X, pos.Y + barHeight / 2)
                    objects.healthBar.To = Vector2.new(barPos.X, (pos.Y + barHeight / 2) - (barHeight * healthPercent))
                    objects.healthBar.Color = barColor
                    objects.healthBar.Visible = true
                else
                    if objects.healthBg then objects.healthBg.Visible = false end
                    if objects.healthBar then objects.healthBar.Visible = false end
                end
            else
                if objects.healthBg then objects.healthBg.Visible = false end
                if objects.healthBar then objects.healthBar.Visible = false end
            end
        else
            if objects.healthBg then objects.healthBg.Visible = false end
            if objects.healthBar then objects.healthBar.Visible = false end
        end
    end)

    ESPObjects[player] = objects
end

local function updateAllESP()
    for _, player in pairs(Players:GetPlayers()) do
