local flySettings = {
    enabled = false,
    speed = 50
}

local RunService = game:GetService("RunService")
local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local Camera = workspace.CurrentCamera

RunService.Stepped:Connect(function()
    if not flySettings.enabled then return end
    
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local seat = hum and hum.SeatPart
    
    if seat and seat:IsA("VehicleSeat") then
        local moveDir = hum.MoveDirection
        
        if moveDir.Magnitude > 0 then
            local localMoveDir = Camera.CFrame:VectorToObjectSpace(moveDir)
            local flyDir = (Camera.CFrame.LookVector * -localMoveDir.Z) + (Camera.CFrame.RightVector * localMoveDir.X)
            
            seat.AssemblyLinearVelocity = flyDir * flySettings.speed
        else
            seat.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        end
        
        seat.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
    end
end)

