local old = nil
local cachedTarget = nil
local lastUpdate = 0
local updateDelay = 0.1
local renderConn = nil
local currentFOV = 100
local wallCheckEnabled = false
local ignoreCivilian = false

local FOV_Circle = Drawing.new("Circle")
FOV_Circle.Visible = false
FOV_Circle.Radius = currentFOV
FOV_Circle.Color = Color3.fromRGB(255, 255, 255)
FOV_Circle.Thickness = 1
FOV_Circle.Transparency = 1
FOV_Circle.Filled = false
FOV_Circle.Position = Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2)

Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
    FOV_Circle.Position = Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2)
end)

local function isEnemy(player)
    local localTeam = LocalPlayer.Team and LocalPlayer.Team.Name or nil
    local targetTeam = player.Team and player.Team.Name or nil
    if not localTeam or not targetTeam then return true end
    return localTeam ~= targetTeam
end

local function isVisible(part)
    if not wallCheckEnabled then return true end
    local origin = Camera.CFrame.Position
    local destination = part.Position
    local direction = destination - origin
    local params = RaycastParams.new()
    params.FilterDescendantsInstances = {LocalPlayer.Character, Camera}
    params.FilterType = Enum.RaycastFilterType.Exclude
    local result = Workspace:Raycast(origin, direction, params)
    if result then
        return result.Instance:IsDescendantOf(part.Parent)
    end
    return true
end

local function isCivilian(player)
    if not ignoreCivilian then return false end
    local char = player.Character
    if char then
        local unit = char:FindFirstChild("Unit")
        if unit and unit.Value == "Civilian" then
            return true
        end
    end
    return false
end

local function updateTarget()
    local closest, dist = nil, math.huge
    local camCF = Camera.CFrame
    local camPos = camCF.Position
    local camLook = camCF.LookVector
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LocalPlayer and isEnemy(p) and not isCivilian(p) then
            local c = p.Character
            if c then
                local head = c:FindFirstChild("Head")
                local hume = c:FindFirstChildOfClass("Humanoid")
                if head and hume and hume.Health > 0 and not c:FindFirstChild("ForceField") then
                    local dir = (head.Position - camPos)
                    local mag = dir.Magnitude
                    local angle = math.deg(math.acos(math.clamp(camLook:Dot(dir.Unit), -1, 1)))
                    local fovAngle = math.deg(math.atan2(currentFOV, Camera.ViewportSize.Y / 2))
                    if angle <= fovAngle and mag < dist then
                        if isVisible(head) then
                            dist = mag
                            closest = head
                        end
                    end
                end
            end
        end
    end
    cachedTarget = closest
end

fistTab:Toggle({
    Title = "Silent Aim",
    Value = false,
    Callback = function(state)
        if state then
            FOV_Circle.Visible = true
            renderConn = RunService.RenderStepped:Connect(function()
                if tick() - lastUpdate > updateDelay then
                    lastUpdate = tick()
                    updateTarget()
                end
            end)
            old = hookmetamethod(game, "__namecall", function(self, ...)
                local method = getnamecallmethod()
                if not checkcaller() and self == Workspace and (method == "Raycast" or method == "FindPartOnRay") then
                    if cachedTarget then
                        local args = {...}
                        local origin, direction
                        if method == "Raycast" then
                            origin, direction = args[1], args[2]
                        else
                            local ray = args[1]
                            if typeof(ray) == "Ray" then
                                origin, direction = ray.Origin, ray.Direction
                            end
                        end
                        if origin and direction then
                            return {
                                Instance = cachedTarget,
                                Position = cachedTarget.Position,
                                Normal = (cachedTarget.Position - origin).Unit,
                                Material = Enum.Material.Plastic
                            }
                        end
                    end
                end
                return old(self, ...)
            end)
        else
            FOV_Circle.Visible = false
            cachedTarget = nil
            if renderConn then
                renderConn:Disconnect()
                renderConn = nil
            end
            if old then
                hookmetamethod(game, "__namecall", old)
                old = nil
            end
        end
    end
})

