local rageSettings = {
    enabled = false,
    mode = "Normal",
    damageRemote = ReplicatedStorage:WaitForChild("TREK_SERVICES"):WaitForChild("TREK_Remotes"):WaitForChild("Damage"),
    ammoRemote = ReplicatedStorage:WaitForChild("TREK_SERVICES"):WaitForChild("TREK_Remotes"):WaitForChild("AmmoRemote"),
    byteNetRemote = ReplicatedStorage:WaitForChild("Libraries"):WaitForChild("ByteNetMax"):WaitForChild("system"):WaitForChild("ByteNetUnreliable")
}

local bruteConnections = {}
local originalProperties = {}
local ignoreCivilian = false

local math_huge = math.huge
local task_wait = task.wait
local task_spawn = task.spawn
local table_insert = table.insert

local function isEnemyPlayer(player)
    if player == LocalPlayer then return false end
    local localTeam = LocalPlayer.Team
    local targetTeam = player.Team
    if not localTeam or not targetTeam then return true end
    return localTeam ~= targetTeam
end

local function isCivilian(player)
    if not ignoreCivilian then return false end
    local char = player.Character
    if char then
        local unit = char:FindFirstChild("Unit")
        if unit and unit.Value == "Civilian" then
            return true
        end
    end
    return false
end

local function getEnemyPlayers()
    local enemies = {}
    for _, player in ipairs(Players:GetPlayers()) do
        if isEnemyPlayer(player) and not isCivilian(player) then
            table_insert(enemies, player)
            if #enemies >= 20 then break end
        end
    end
    return enemies
end

local function setPartNoCollision(part, state)
    if not part or not part:IsA("BasePart") then return end
    if state then
        if originalProperties[part] == nil then
            originalProperties[part] = part.CanCollide
        end
        part.CanCollide = false
    else
        if originalProperties[part] ~= nil then
            part.CanCollide = originalProperties[part]
            originalProperties[part] = nil
        end
    end
end

local function isVehicleModel(model)
    if not model or not model:IsA("Model") then return false end
    if model:FindFirstChildOfClass("VehicleSeat") then return true end
    if model:FindFirstChild("DriveSeat") then return true end
    if model:FindFirstChild("Engine") then return true end
    return false
end

local function setVehiclesNoCollision(state)
    local workspace = game:GetService("Workspace")
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("Model") and isVehicleModel(obj) then
            local isPlayerChar = false
            for _, player in ipairs(Players:GetPlayers()) do
                if player.Character == obj then
                    isPlayerChar = true
                    break
                end
            end
            if not isPlayerChar then
                for _, part in ipairs(obj:GetDescendants()) do
                    if part:IsA("BasePart") then
                        setPartNoCollision(part, state)
                    end
                end
            end
        end
    end
end

local function restoreAllCollisions()
    for part, value in pairs(originalProperties) do
        if part and part.Parent then
            part.CanCollide = value
        end
    end
    originalProperties = {}
end

local function keepPlayerGrounded()
    local myChar = LocalPlayer.Character
    if not myChar then return end
    local myRoot = myChar:FindFirstChild("HumanoidRootPart")
    local hum = myChar:FindFirstChild("Humanoid")
    if not myRoot or not hum then return end
    hum.PlatformStand = false
    local vel = myRoot.AssemblyLinearVelocity
    if vel.Y > 5 then
        myRoot.AssemblyLinearVelocity = Vector3.new(vel.X, 0, vel.Z)
    end
end

local function stopBruteMode()
    for _, conn in ipairs(bruteConnections) do
        if typeof(conn) == "RBXScriptConnection" then
            conn:Disconnect()
        end
    end
    bruteConnections = {}
    restoreAllCollisions()
end

local function startBruteMode()
    stopBruteMode()
    setVehiclesNoCollision(true)

    local descConn = game:GetService("Workspace").DescendantAdded:Connect(function(obj)
        task_wait()
        if obj:IsA("Model") and isVehicleModel(obj) then
            local isPlayerChar = false
            for _, player in ipairs(Players:GetPlayers()) do
                if player.Character == obj then
                    isPlayerChar = true
                    break
                end
            end
            if not isPlayerChar then
                for _, part in ipairs(obj:GetDescendants()) do
                    if part:IsA("BasePart") then
                        setPartNoCollision(part, true)
                    end
                end
            end
        elseif obj:IsA("BasePart") then
            local model = obj:FindFirstAncestorOfClass("Model")
            if model and isVehicleModel(model) then
                setPartNoCollision(obj, true)
            end
        end
    end)
    table_insert(bruteConnections, descConn)

    local teamConn = LocalPlayer:GetPropertyChangedSignal("Team"):Connect(function()
        setVehiclesNoCollision(true)
    end)
    table_insert(bruteConnections, teamConn)

    local charAddedConn = LocalPlayer.CharacterAdded:Connect(function()
        task_wait(0.1)
        setVehiclesNoCollision(true)
    end)
    table_insert(bruteConnections, charAddedConn)

    task_spawn(function()
        while rageSettings.enabled and rageSettings.mode == "Brute" do
            local myChar = LocalPlayer.Character
            local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
            if myRoot then
                local enemies = getEnemyPlayers()
                for _, enemy in ipairs(enemies) do
                    local eChar = enemy.Character
                    local eRoot = eChar and eChar:FindFirstChild("HumanoidRootPart")
                    local hum = eChar and eChar:FindFirstChild("Humanoid")
                    if eRoot and hum and hum.Health > 0 then
                        local front = myRoot.CFrame * CFrame.new(0, 0, -5)
                        eRoot.CFrame = front
                    end
                end
                keepPlayerGrounded()
            end
            task_wait(0.05)
        end
    end)
end

local function getClosestEnemyRage()
    local closest = nil
    local shortestDistance = math_huge
    local myChar = LocalPlayer.Character
    if not myChar or not myChar:FindFirstChild("HumanoidRootPart") then return nil end
    for _, player in ipairs(Players:GetPlayers()) do
        if isEnemyPlayer(player) and not isCivilian(player) then
            local char = player.Character
            if char and char:FindFirstChild("Head") and char:FindFirstChild("Humanoid") then
                if char.Humanoid.Health > 0 and not char:FindFirstChild("ForceField") then
                    local dist = (char.Head.Position - myChar.HumanoidRootPart.Position).Magnitude
                    if dist < shortestDistance then
                        shortestDistance = dist
                        closest = char.Head
                    end
                end
            end
        end
    end
    return closest
end

local function getWeaponBarrel()
    local char = LocalPlayer.Character
    if not char then return nil end
    local tool = char:FindFirstChildOfClass("Tool")
    if tool then
        return tool:FindFirstChild("Barrel")
    end
    return nil
end

local byteNetBuf = buffer.fromstring("\f\000\001\001\v\245\2050/\247\n\197\254\222\158Bzp\018E\001\t\227W\197\255\248\159B\170a\158E")

local function fireRageSequence()
    local targetHead = getClosestEnemyRage()
    if not targetHead then return end
    local barrel = getWeaponBarrel()
    if not barrel then return end
    local hitPos = targetHead.Position
    task_spawn(function()
        rageSettings.byteNetRemote:FireServer(byteNetBuf, {barrel})
        rageSettings.ammoRemote:FireServer(1)
        rageSettings.damageRemote:FireServer(hitPos, targetHead, Vector3.new(2, 1, 1), 1)
    end)
end

fistTab:Toggle({
    Title = "Ragebot",
    Desc = "if brute mode has no damage keep pressing jump, if you're on the reactor maintenance team go outside first (just try it yourself)",
    Value = false,
    Callback = function(state)
        rageSettings.enabled = state
        if state then
            if rageSettings.mode == "Brute" then
                startBruteMode()
            end
            task_spawn(function()
                while rageSettings.enabled do
                    fireRageSequence()
                    task_wait(0.05)
                end
            end)
        else
            stopBruteMode()
        end
    end
})

