local supportedGuns = {AK47 = true, C4 = true, Deagle = true, Fortnite = true, P250 = true, Remington = true, ["Spas 12"] = true}
local attackInterval = 0.5
local attackRange = 200
local mode = "Player"
local lastShot = 0
local lastReload = 0
local rageBotEnabled = false
local rayVisualizationEnabled = false
local hitSoundEnabled = false
local tracerColor = Color3.fromRGB(255, 0, 0)
local tracerWidth = 1
local tracerLifetime = 3
local tracerTexture = "Laser"
local rageBotConnection

local tracerTextures = {
    ["Default"] = "rbxassetid://7136858729",
    ["Alternative"] = "rbxassetid://6060542021",
    ["Laser"] = "rbxassetid://446111271",
    ["Rainbow"] = "rbxassetid://875688442"
}

local function getEquippedWeapon()
    local character = LocalPlayer.Character
    if not character then return end
    for _, item in ipairs(character:GetChildren()) do
        if item:IsA("Tool") and supportedGuns[item.Name] then return item end
    end
end

local function isPlayerDead(character)
    if not character then return true end
    local humanoid = character:FindFirstChild("Humanoid")
    return not humanoid or humanoid.Health <= 0
end

local function getClosestTarget()
    local localChar = LocalPlayer.Character
    if not localChar or not localChar:FindFirstChild("HumanoidRootPart") then return nil end
    local hrpPos = localChar.HumanoidRootPart.Position
    local closest, minDist = nil, attackRange

    if mode == "NPC" and humansFolder then
        for _, v in ipairs(humansFolder:GetChildren()) do
            local hrp = v:FindFirstChild("HumanoidRootPart")
            if hrp and v ~= localChar and not isPlayerDead(v) then
                local dist = (hrp.Position - hrpPos).Magnitude
                if dist < minDist then minDist = dist closest = v end
            end
        end
    else
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and not isPlayerDead(p.Character) then
                local dist = (p.Character.HumanoidRootPart.Position - hrpPos).Magnitude
                if dist < minDist then minDist = dist closest = p.Character end
            end
        end
    end
    return closest
end

local function createRayVisualization(startPos, endPos)
    if not rayVisualizationEnabled then return end
    local container = Instance.new("Part")
    container.Name = "TracerPart"
    container.Size = Vector3.new(0, 0, 0)
    container.Transparency = 1
    container.CanCollide = false
    container.Anchored = true
    container.Parent = workspace

    local a0 = Instance.new("Attachment", container)
    local a1 = Instance.new("Attachment", container)
    a0.WorldPosition = startPos
    a1.WorldPosition = endPos

    local beam = Instance.new("Beam", container)
    beam.Attachment0 = a0
    beam.Attachment1 = a1
    beam.Color = ColorSequence.new(tracerColor)
    beam.Width0, beam.Width1 = tracerWidth, tracerWidth
    beam.Texture = tracerTextures[tracerTexture] or tracerTextures["Laser"]
    beam.LightEmission = 1
    beam.TextureSpeed = 1
    
    task.spawn(function()
        local tween = TweenService:Create(beam, TweenInfo.new(tracerLifetime), {Brightness = 0})
        tween:Play()
        task.wait(tracerLifetime)
        container:Destroy()
    end)
end

local function fireAtTarget(target)
    local weapon = getEquippedWeapon()
    if not weapon or not target:FindFirstChild("Head") then return end
    
    local character = LocalPlayer.Character
    local muzzlePos = (character and character:FindFirstChild("HumanoidRootPart")) and character.HumanoidRootPart.Position or target.Head.Position + Vector3.new(0, 10, 0)
    local hitPart = target:FindFirstChild("Head")
    local hitPos = hitPart.Position

    ReplicatedStorage.Remotes.Fire:FireServer(weapon, "Fire", {
        bullet = ReplicatedStorage.Models.Bullets.Default,
        direction = (hitPos - muzzlePos).Unit,
        velocity = 5000,
        origin = muzzlePos
    })
    ReplicatedStorage.Remotes.Fire:FireServer(weapon.Name, "Hit", {
        normal = Vector3.new(0, 1, 0),
        velocity = (hitPos - muzzlePos).Unit * 5000,
        position = hitPos,
        hit = hitPart
    })
    
    if rayVisualizationEnabled then 
        createRayVisualization(muzzlePos, hitPos) 
    end
    
    if hitSoundEnabled then
        local s = Instance.new("Sound", workspace)
        s.SoundId = "rbxassetid://5633695679"
        s:Play()
        Debris:AddItem(s, 0.5)
    end
end

fistTab:Toggle({
    Title = "ragebot",
    Value = false,
    Callback = function(state)
        rageBotEnabled = state
        if rageBotConnection then rageBotConnection:Disconnect() end
        if state then
            rageBotConnection = RunService.RenderStepped:Connect(function()
                if tick() - lastReload >= 0.3 then
                    local w = getEquippedWeapon()
                    if w then ReplicatedStorage.Remotes.Reload:InvokeServer(w) lastReload = tick() end
                end
                if tick() - lastShot >= attackInterval then
                    local target = getClosestTarget()
                    if target then fireAtTarget(target) lastShot = tick() end
                end
            end)
        end
    end
})

fistTab:Toggle({Title = "ragebot打击声音", Value = false, Callback = function(s) hitSoundEnabled = s end})
fistTab:Toggle({Title = "ragebot射线", Value = false, Callback = function(s) rayVisualizationEnabled = s end})
