fistTab:Slider({Title = "射线宽度", Value = {Min = 0.1, Max = 5, Default = 1}, Callback = function(v) tracerWidth = v end})
fistTab:Slider({Title = "射线持续时间", Value = {Min = 0.5, Max = 10, Default = 3}, Callback = function(v) tracerLifetime = v end})
fistTab:Dropdown({Title = "射线纹理", Multi = false, Value = "Laser", Values = {"Default", "Alternative", "Laser", "Rainbow"}, Callback = function(v) tracerTexture = v end})

local auraState = false
local auraConnection
fistTab:Toggle({
    Title = "斧头杀戮光环",
    Value = false,
    Callback = function(state)
        auraState = state
        if auraConnection then auraConnection:Disconnect() end
        if state then
            auraConnection = RunService.Stepped:Connect(function()
                local weapon = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Fire Axe")
                local target = getClosestTarget()
                if weapon and target and target:FindFirstChild("Head") then
                    ReplicatedStorage.Remotes.Swing:FireServer(weapon, "Hit", target.Head)
                end
            end)
        end
    end
})

local stompEnabled = false
fistTab:Toggle({
    Title = "全图秒杀",
    Value = false,
    Callback = function(state)
        stompEnabled = state
        if state then
            task.spawn(function()
                while stompEnabled do
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("Head") then
                            local hum = p.Character:FindFirstChild("Humanoid")
                            if hum and hum.Health > 0 then
                                ReplicatedStorage.Remotes.Swing:FireServer("Stomp Air", "Stomp Air Start")
                                ReplicatedStorage.Remotes.Swing:FireServer("Stomp Air", "Stomp Air Hit", p.Character.Head)
                            end
                        end
                    end
                    task.wait(0.1)
                end
            end)
        end
    end
})

