local headEnlargeEnabled = false
local originalHeadData = {}
local humansFolder = workspace:FindFirstChild("Humans")

local function enlargeHead(model)
    local head = model:FindFirstChild("Head")
    if head and head:IsA("BasePart") then
        if not originalHeadData[model] then
            originalHeadData[model] = {Size = head.Size, Transparency = head.Transparency}
        end
        head.Size = Vector3.new(10, 10, 10)
        head.Transparency = 0.5
        head.CanCollide = false
        head.Massless = true
    end
end

local function resetHead(model)
    local head = model:FindFirstChild("Head")
    if head and head:IsA("BasePart") then
        local original = originalHeadData[model]
        if original then
            head.Size = original.Size
            head.Transparency = original.Transparency
            head.CanCollide = true
            head.Massless = false
        end
    end
end

