    Title = "head hitboxes",
    Value = false,
    Callback = function(state)
        headEnlargeEnabled = state
        if humansFolder then
            for _, model in pairs(humansFolder:GetChildren()) do
                if model:IsA("Model") and model.Name ~= LocalPlayer.Name then
                    if state then enlargeHead(model) else resetHead(model) end
                end
            end
        end
    end
})

