local function tsbeng()
Window:Divider()
local Tab = Window:Tab({  
    Title = "function",  
    Icon = "house",  
    Locked = false,
})
local Players = game:GetService("Players")
local Settings = {
    DashCooldown = 5,
    SkipRagdollDelay = false,
    DashEnabled = false
}

local LastDashTime = 0
local FakeDashReset = Instance.new("Folder")
FakeDashReset.Name = "DashReset3rd"

local Character = Players.LocalPlayer.Character or Players.LocalPlayer.CharacterAdded:Wait()

local function listenToCharacter(char)
    Character = char
    local HRP = char:WaitForChild("HumanoidRootPart", 5)
    if HRP then
        HRP.ChildAdded:Connect(function(child)
            if child.Name == "dodgevelocity" and child:IsA("BodyVelocity") then
                LastDashTime = tick()
            end
        end)
    end
end

if Character then listenToCharacter(Character) end
Players.LocalPlayer.CharacterAdded:Connect(listenToCharacter)

local oldNamecall
oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
    local method = getnamecallmethod()
    local args = { ... }
    
    if not checkcaller() and self == Character then
        if method == "FindFirstChild" then
            local name = args[1]
            if Settings.DashEnabled and name == "DashReset3rd" then
                if tick() - LastDashTime >= Settings.DashCooldown then
                    return FakeDashReset
                end
            end
            if Settings.SkipRagdollDelay and (name == "Ragdoll" or name == "FakeRagdoll") then
                return nil
            end
        elseif method == "GetAttribute" and args[1] == "AfterimageDash" then
            if Settings.DashEnabled and (tick() - LastDashTime >= Settings.DashCooldown) then
                return 999
            end
        end
    end
    
    return oldNamecall(self, ...)
end))

Tab:Toggle({
    Title = "no dash cooldown",
    Value = false,
    Callback = function(state)
        Settings.DashEnabled = state
    end
})

Tab:Input({
    Title = "dash cooldown value",
    Value = tostring(Settings.DashCooldown),
    Placeholder = "don't in put 0",
    Callback = function(input)
        local val = tonumber(input)
        if val then
            Settings.DashCooldown = val
        end
    end
})

