local LockTab = Window:Tab({
    Title = "lock player",
    Icon = "target",
    Locked = false,
})
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local localPlayer = Players.LocalPlayer

local BEHIND_DISTANCE = 5
local circleRadius = 6
local circleSpeed = 13
local circleAngle = 0

local followEnabled = false
local circleEnabled = false
local lookEnabled = false
local selectedTargetName = nil
local autoFlingEnabled = false
local originalPosition = nil

getgenv().FPDH = workspace.FallenPartsDestroyHeight

local function getHRP(p)
    if p and p.Character then
        return p.Character:FindFirstChild("HumanoidRootPart")
    end
end

local function getPlayerNames()
    local names = {}
    local allPlayers = Players:GetPlayers()
    for i = 1, #allPlayers do
        local p = allPlayers[i]
        if p ~= localPlayer then
            table.insert(names, p.Name)
        end
    end
    return #names > 0 and names or {"No Players"}
end

local function forceRefreshUI()
    local pList = getPlayerNames()
    if playerDropdown then
        if playerDropdown.Refresh then
            playerDropdown:Refresh(pList, true)
        elseif playerDropdown.SetValues then
            playerDropdown:SetValues(pList)
        end
    end
end

RunService.RenderStepped:Connect(function(dt)
    if not selectedTargetName or selectedTargetName == "No Players" or autoFlingEnabled then return end
    
    local myHRP = getHRP(localPlayer)
    local target = Players:FindFirstChild(selectedTargetName)
    local targetHRP = target and getHRP(target)
    
    if not (myHRP and targetHRP) then return end

    if followEnabled then
        local pos = targetHRP.Position - targetHRP.CFrame.LookVector * BEHIND_DISTANCE
        if lookEnabled then
            myHRP.CFrame = CFrame.new(pos, Vector3.new(targetHRP.Position.X, pos.Y, targetHRP.Position.Z))
        else
            myHRP.CFrame = CFrame.new(pos.X, targetHRP.Position.Y, pos.Z)
        end
    elseif circleEnabled then
        circleAngle = circleAngle + circleSpeed * dt
        local x = math.cos(circleAngle) * circleRadius
        local z = math.sin(circleAngle) * circleRadius
        local p = targetHRP.Position + Vector3.new(x, 0, z)
        if lookEnabled then
            myHRP.CFrame = CFrame.new(p, Vector3.new(targetHRP.Position.X, p.Y, targetHRP.Position.Z))
        else
            myHRP.CFrame = CFrame.new(p.X, targetHRP.Position.Y, p.Z)
        end
    elseif lookEnabled then
        local myPos = myHRP.Position
        local tp = targetHRP.Position
        myHRP.CFrame = CFrame.new(myPos, Vector3.new(tp.X, myPos.Y, tp.Z))
    end
end)

playerDropdown = LockTab:Dropdown({
    Title = "Select Target",
    Multi = false,
    AllowNone = true,
    Values = getPlayerNames(),
    Callback = function(selected)
        selectedTargetName = typeof(selected) == "table" and selected[1] or selected
    end
})

LockTab:Button({
    Title = "Refresh Players",
    Callback = function()
        forceRefreshUI()
    end
})

LockTab:Toggle({
    Title = "Stick Behind",
    Value = false,
    Callback = function(state)
        followEnabled = state
        if state then circleEnabled = false end
    end
})

LockTab:Toggle({
    Title = "Orbit Mode",
    Value = false,
    Callback = function(state)
        circleEnabled = state
        if state then followEnabled = false end
    end
})

LockTab:Toggle({
    Title = "Face Target",
    Value = false,
    Callback = function(state)
        lookEnabled = state
    end
})

LockTab:Toggle({
    Title = "fling target player",
    Value = false,
    Callback = function(state)
        autoFlingEnabled = state
        local char = localPlayer.Character
        local hrp = getHRP(localPlayer)
        local hum = char and char:FindFirstChildOfClass("Humanoid")

        if state then
            if hrp then originalPosition = hrp.CFrame end
            workspace.FallenPartsDestroyHeight = 0/0
            
            task.spawn(function()
                local bv = Instance.new("BodyVelocity")
                bv.Name = "EpixVel"
                bv.Parent = hrp
                bv.Velocity = Vector3.new(9e8, 9e8, 9e8)
                bv.MaxForce = Vector3.new(1/0, 1/0, 1/0)
                hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false)

                local angle = 0
                while autoFlingEnabled do
                    if selectedTargetName and selectedTargetName ~= "No Players" then
                        local targetPlayer = Players:FindFirstChild(selectedTargetName)
                        local tChar = targetPlayer and targetPlayer.Character
                        local tHRP = tChar and tChar:FindFirstChild("HumanoidRootPart")
                        local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")

                        if tHRP and hrp and tHum then
                            angle = angle + 100
                            local moveDir = tHum.MoveDirection
                            local velMag = tHRP.Velocity.Magnitude
                            
                            local function flingPos(offset, rot)
                                hrp.CFrame = CFrame.new(tHRP.Position) * offset * rot
                                hrp.Velocity = Vector3.new(9e7, 9e7 * 10, 9e7)
                                hrp.RotVelocity = Vector3.new(9e8, 9e8, 9e8)
                            end

                            flingPos(CFrame.new(0, 1.5, 0) + moveDir * velMag / 1.25, CFrame.Angles(math.rad(angle), 0, 0))
                            task.wait()
                            flingPos(CFrame.new(0, -1.5, 0) + moveDir * velMag / 1.25, CFrame.Angles(math.rad(angle), 0, 0))
                            task.wait()
                        end
                    end
                    task.wait()
                end
                bv:Destroy()
                hum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
                workspace.FallenPartsDestroyHeight = getgenv().FPDH
            end)
        else
            if hrp and originalPosition then
                hrp.Velocity = Vector3.new(0,0,0)
                hrp.RotVelocity = Vector3.new(0,0,0)
                hrp.CFrame = originalPosition
                hum:ChangeState("GettingUp")
            end
        end
    end
})




