        _G.AutoPickupMoney = state
        
        local function AutoPickupMoneyEnable()
            if _G.AutoPickupMoneyEnabled then return end
            _G.AutoPickupMoneyEnabled = true
            
            _G.AutoPickupMoneyConnection = game:GetService("RunService").Heartbeat:Connect(function()
                if not _G.AutoPickupMoney then return end
                
                local cashFolder = workspace:FindFirstChild("Filter") and workspace.Filter:FindFirstChild("SpawnedBread")
                local eventsFolder = game:GetService("ReplicatedStorage"):FindFirstChild("Events")
                local remoteEvent = eventsFolder and eventsFolder:FindFirstChild("CZDPZUS")
                
                if not cashFolder or not remoteEvent then return end
                
                local player = game:GetService("Players").LocalPlayer
                local character = player and player.Character
                local hrp = character and character:FindFirstChild("HumanoidRootPart")
                
                if not hrp or (_G.MoneyCooldown) then return end
                
                local rootPosition = hrp.Position
                for _, v in ipairs(cashFolder:GetChildren()) do
                    if v:IsA("BasePart") and (rootPosition - v.Position).Magnitude <= 5 then
                        if not _G.MoneyCooldown then
                            _G.MoneyCooldown = true
                            pcall(function() remoteEvent:FireServer(v) end)
                            task.wait(1.1)
                            _G.MoneyCooldown = false
                            break
                        end
                    end
                end
            end)
