            if _G.AutoPickupMoneyConnection then
                _G.AutoPickupMoneyConnection:Disconnect()
                _G.AutoPickupMoneyConnection = nil
            end
            _G.MoneyCooldown = false
        end

        if state then
            AutoPickupMoneyEnable()
        else
            AutoPickupMoneyDisable()
        end
