PlayerESP.RunService.Heartbeat:Connect(function()
    local allPlayers = {}
    for player, _ in pairs(PlayerESP.trackedPlayers) do
        if player.Parent and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
            local dist = PlayerESP.LocalPlayer:DistanceFromCharacter(player.Character.HumanoidRootPart.Position)
            table.insert(allPlayers, {plr = player, dist = dist})
        end
    end
    
    table.sort(allPlayers, function(a, b) return a.dist < b.dist end)

    for player, _ in pairs(PlayerESP.trackedPlayers) do
        if player.Character then
            PlayerESP.applyESP(player.Character, false)
        end
    end

    for i, data in ipairs(allPlayers) do
        if PlayerESP.espEnabled and i <= 30 then
            PlayerESP.applyESP(data.plr.Character, true)
        end
    end
end)

