local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LocalPlayer = Players.LocalPlayer
local safeEspEnabled = false
local safeNameEspEnabled = false
local safeEspColor = Color3.fromRGB(200, 150, 255)
local safeNameEspColor = Color3.fromRGB(200, 150, 255)

local trackedObjects = {}

local function getValidPart(obj)
    if obj:IsA("BasePart") then return obj end
    return obj.PrimaryPart or obj:FindFirstChildWhichIsA("BasePart", true)
end

local function updateNames(obj, part, state)
    local billboard = part:FindFirstChild("SafeNameESP")
    if state then
        if not billboard then
            billboard = Instance.new("BillboardGui")
            billboard.Name = "SafeNameESP"
            billboard.AlwaysOnTop = true
            billboard.Size = UDim2.new(0, 100, 0, 25)
            billboard.StudsOffset = Vector3.new(0, 3, 0)
            billboard.Parent = part
            local label = Instance.new("TextLabel")
            label.BackgroundTransparency = 1
            label.Size = UDim2.new(1, 0, 1, 0)
            label.TextSize = 12
            label.Font = Enum.Font.SourceSansBold
            label.Parent = billboard
        end
        local lowerName = obj.Name:lower()
        local displayName = "safe"
        if lowerName:find("small") then displayName = "small safe"
        elseif lowerName:find("medium") then displayName = "medium safe"
        elseif lowerName:find("register") then displayName = "cash register" end
        billboard.TextLabel.Text = displayName
        billboard.TextLabel.TextColor3 = safeNameEspColor
    elseif billboard then
        billboard:Destroy()
    end
end

local function updateHighlight(obj, state)
    local highlight = obj:FindFirstChild("SafeHighlight")
    if state then
        if not highlight then
            highlight = Instance.new("Highlight")
            highlight.Name = "SafeHighlight"
            highlight.FillTransparency = 0.5
            highlight.OutlineTransparency = 0
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            highlight.Parent = obj
        end
        highlight.FillColor = safeEspColor
        highlight.OutlineColor = safeEspColor
    elseif highlight then
        highlight:Destroy()
    end
end

local function scanFolder(folder)
    for _, obj in ipairs(folder:GetDescendants()) do
        if obj:IsA("Model") or obj:IsA("BasePart") then
            local lowerName = obj.Name:lower()
            if lowerName:find("safe") or lowerName:find("register") then
                local part = getValidPart(obj)
                if part and not trackedObjects[obj] then
                    trackedObjects[obj] = part
                end
            end
        end
    end
end

RunService.Heartbeat:Connect(function()
    local folder = workspace:FindFirstChild("Map") and workspace.Map:FindFirstChild("BredMakurz")
    if not folder then return end

    scanFolder(folder)

    local targets = {}
    for obj, part in pairs(trackedObjects) do
        if obj.Parent and part.Parent then
            local dist = LocalPlayer:DistanceFromCharacter(part.Position)
            table.insert(targets, {obj = obj, part = part, dist = dist})
            updateNames(obj, part, safeNameEspEnabled)
        else
            trackedObjects[obj] = nil
        end
    end

    table.sort(targets, function(a, b) return a.dist < b.dist end)

    for obj, _ in pairs(trackedObjects) do
        updateHighlight(obj, false)
    end

    for i, data in ipairs(targets) do
        if safeEspEnabled and i <= 30 then
            updateHighlight(data.obj, true)
        end
    end
end)

