            ConfigTable.Ragebot.UseTargetList = true
            for i = #Whitelist, 1, -1 do 
                if Whitelist[i] == name then table.remove(Whitelist, i) end 
            end
            local exists = false
            for i = 1, #TargetList do
                if TargetList[i] == name then exists = true break end
            end
            if not exists then table.insert(TargetList, name) end
            forceRefreshUI()
        end
    end
})

