local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local LocalPlayer = Players.LocalPlayer
local MapPath = workspace:WaitForChild("Map"):WaitForChild("BredMakurz")
local Event1 = ReplicatedStorage:WaitForChild("Events"):WaitForChild("XMHH.2")
local Event2 = ReplicatedStorage:WaitForChild("Events"):WaitForChild("XMHH2.2")

local Running = false
local GetChildren = game.GetChildren
local sub = string.sub
local _tick = tick

local function GetClosest()
    local char = LocalPlayer.Character
    if not char then return nil end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return nil end
    
    local rootPos = root.Position
    local target, dist = nil, 10
    local children = GetChildren(MapPath)
    
    for i = 1, #children do
        local v = children[i]
        if sub(v.Name, 1, 8) == "Register" then
            local part = v:FindFirstChild("MainPart")
            if part then
                local d = (part.Position - rootPos).Magnitude
                if d < dist then
                    dist = d
                    target = v
                end
            end
        end
    end
    return target
end

task.spawn(function()
    while true do
        if not Running then 
            task.wait(0.5)
        else
            local char = LocalPlayer.Character
            local fists = char and char:FindFirstChild("Fists")
            
            if fists then
                local target = GetClosest()
                if target then
                    local main = target:FindFirstChild("MainPart")
                    local root = char:FindFirstChild("HumanoidRootPart")
                    local arm = char:FindFirstChild("Right Arm")
                    
                    if main and root and arm then
                        pcall(function()
                            local val = Event1:InvokeServer("\240\159\141\158", _tick(), fists, "DZDRRRKI", target, "Register")
                            if val then
                                local mPos = main.Position
                                local rPos = root.Position
                                for i = 1, 5 do
                                    Event2:FireServer("\240\159\141\158", _tick(), fists, "2389ZFX34", val, false, arm, main, target, mPos, rPos)
                                end
                            end
                        end)
                    end
                end
            end
            task.wait(0.2)
        end
    end
end)

