local backups = {}
local featureCache = {}

local function manageFeature(key, state, fields, value)
    if state then
        if not featureCache[key] then
            featureCache[key] = {}
            for _, v in pairs(getgc(true)) do
                if type(v) == "table" and not rawget(v, "__index") then 
                    for _, field in pairs(fields) do
                        local currentVal = rawget(v, field)
                        if currentVal ~= nil and type(currentVal) == "number" then
                            if not backups[v] then backups[v] = {} end
                            if backups[v][field] == nil then
                                backups[v][field] = currentVal
                            end
                            table.insert(featureCache[key], {obj = v, prop = field})
                        end
                    end
                end
            end
        end
        
        for _, data in pairs(featureCache[key]) do
            pcall(function() data.obj[data.prop] = value end)
        end
    else
        if featureCache[key] then
            for _, data in pairs(featureCache[key]) do
                local original = backups[data.obj] and backups[data.obj][data.prop]
                if original ~= nil then
                    pcall(function() data.obj[data.prop] = original end)
                end
            end
            featureCache[key] = nil
        end
    end
end

