local PlayerESP = {}

PlayerESP.Players = game:GetService("Players")
PlayerESP.RunService = game:GetService("RunService")
PlayerESP.LocalPlayer = PlayerESP.Players.LocalPlayer
PlayerESP.espEnabled = false
PlayerESP.espColor = Color3.fromRGB(0, 255, 0)
PlayerESP.trackedPlayers = {}

function PlayerESP.applyESP(character, state)
    local highlight = character:FindFirstChild("PlayerESP")
    if state then
        if not highlight then
            highlight = Instance.new("Highlight")
            highlight.Name = "PlayerESP"
            highlight.FillTransparency = 0.5
            highlight.OutlineTransparency = 0
            highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
            highlight.Parent = character
        end
        highlight.Adornee = character
        highlight.FillColor = PlayerESP.espColor
        highlight.OutlineColor = PlayerESP.espColor
    elseif highlight then
        highlight:Destroy()
    end
end

PlayerESP.Players.PlayerAdded:Connect(function(player)
    PlayerESP.trackedPlayers[player] = true
    player.CharacterAdded:Connect(function(character)
        character:WaitForChild("HumanoidRootPart")
    end)
end)

PlayerESP.Players.PlayerRemoving:Connect(function(player)
    PlayerESP.trackedPlayers[player] = nil
end)

for _, player in ipairs(PlayerESP.Players:GetPlayers()) do
    if player ~= PlayerESP.LocalPlayer then
        PlayerESP.trackedPlayers[player] = true
    end
end

PlayerESP.RunService.Heartbeat:Connect(function()
    local allPlayers = {}
    for player, _ in pairs(PlayerESP.trackedPlayers) do
        if player.Parent and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
            local dist = PlayerESP.LocalPlayer:DistanceFromCharacter(player.Character.HumanoidRootPart.Position)
            table.insert(allPlayers, {plr = player, dist = dist})
        end
    end
    
    table.sort(allPlayers, function(a, b) return a.dist < b.dist end)

    for player, _ in pairs(PlayerESP.trackedPlayers) do
        if player.Character then
            PlayerESP.applyESP(player.Character, false)
        end
    end

    for i, data in ipairs(allPlayers) do
        if PlayerESP.espEnabled and i <= 30 then
            PlayerESP.applyESP(data.plr.Character, true)
        end
    end
end)

