local shopEspEnabled = false
local shopEspColor = Color3.fromRGB(255, 255, 255)
local shopEspConnections = {}

local function createShopEsp(obj)
    if not obj:IsA("Model") and not obj:IsA("Part") then return end
    local highlight = Instance.new("Highlight")
    highlight.Name = "ShopESP"
    highlight.Adornee = obj
    highlight.FillColor = shopEspColor
    highlight.OutlineColor = shopEspColor
    highlight.FillTransparency = 0.6
    highlight.OutlineTransparency = 0
    highlight.Parent = obj
