local function addShopEsp()
    if not workspace:FindFirstChild("Map") or not workspace.Map:FindFirstChild("Shopz") then return end
    for _, v in ipairs(workspace.Map.Shopz:GetDescendants()) do
        if v:IsA("Model") or v:IsA("Part") then
            createShopEsp(v)
        end
    end
    shopEspConnections["ChildAdded"] = workspace.Map.Shopz.DescendantAdded:Connect(function(v)
        if v:IsA("Model") or v:IsA("Part") then
            createShopEsp(v)
        end
    end)
end

