local function createHitNotification(toolName, offsetValue, playerName)
    if not ConfigTable.Ragebot.HitNotify then return end
    
    local targetPlayer = Players:FindFirstChild(playerName)
    local char = targetPlayer and targetPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local health = hum and math.floor(hum.Health) or 0

    local ScreenGui = CoreGui:FindFirstChild("HitNotifications")
    if not ScreenGui then
        ScreenGui = Instance.new("ScreenGui")
        ScreenGui.Name = "HitNotifications"
        ScreenGui.ResetOnSpawn = false
        ScreenGui.Parent = CoreGui
    end
    
    local scrollFrame = ScreenGui:FindFirstChild("NotificationScroll")
    if not scrollFrame then
        scrollFrame = Instance.new("Frame")
        scrollFrame.Name = "NotificationScroll"
        scrollFrame.Parent = ScreenGui
        scrollFrame.BackgroundTransparency = 1
        scrollFrame.Size = UDim2.new(0, 350, 1, 0)
        scrollFrame.Position = UDim2.new(0, 15, 0, 15)
    end

    local box = Instance.new("Frame")
    box.Name = "NotifBox"
    box.Parent = scrollFrame
    box.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
    box.BackgroundTransparency = 0.35
    box.BorderSizePixel = 0
    box.Position = UDim2.new(-1.2, 0, 0, #hitNotifications * 32)

    local uiCorner = Instance.new("UICorner")
    uiCorner.CornerRadius = UDim.new(0, 4)
    uiCorner.Parent = box

    local uiStroke = Instance.new("UIStroke")
    uiStroke.Thickness = 1.2
    uiStroke.Color = ConfigTable.Ragebot.HitColor
    uiStroke.Transparency = 0.5
    uiStroke.Parent = box

    local parts = {
        {"Hit ", Color3.fromRGB(255, 255, 255)},
        {playerName .. " ", ConfigTable.Ragebot.HitColor},
        {"| HP: ", Color3.fromRGB(200, 200, 200)},
        {tostring(health) .. " ", Color3.fromRGB(0, 255, 150)},
        {"| Dist: ", Color3.fromRGB(200, 200, 200)},
        {string.format("%.1f", offsetValue), ConfigTable.Ragebot.HitColor}
    }

    local offsetX = 10
    for _, seg in ipairs(parts) do
        local label = Instance.new("TextLabel")
        label.Parent = box
        label.BackgroundTransparency = 1
        label.TextColor3 = seg[2]
        label.Font = Enum.Font.GothamBold
        label.TextSize = 11
        label.Text = seg[1]
        label.Position = UDim2.new(0, offsetX, 0.5, 0)
        label.AnchorPoint = Vector2.new(0, 0.5)
        label.AutomaticSize = Enum.AutomaticSize.XY
        
        local textX = label.TextBounds.X
        if textX == 0 then textX = #seg[1] * 6 end
        offsetX = offsetX + textX
    end
    
    box.Size = UDim2.new(0, offsetX + 10, 0, 26)
    table.insert(hitNotifications, {box = box, createTime = tick()})

    local function updateLayout()
        for i, notif in ipairs(hitNotifications) do
            if notif.box and notif.box.Parent then
                TweenService:Create(notif.box, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                    Position = UDim2.new(0, 0, 0, (i - 1) * 32)
                }):Play()
            end
        end
    end

    TweenService:Create(box, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Position = UDim2.new(0, 0, 0, (#hitNotifications - 1) * 32)
    }):Play()
    
    updateLayout()

    task.delay(ConfigTable.Ragebot.HitNotifyDuration, function()
        if box and box.Parent then
            local outTween = TweenService:Create(box, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
                Position = UDim2.new(-1.2, 0, 0, box.Position.Y.Offset),
                BackgroundTransparency = 1
            })
            outTween:Play()
            outTween.Completed:Connect(function()
                for i, notif in ipairs(hitNotifications) do
                    if notif.box == box then
                        table.remove(hitNotifications, i)
                        break
                    end
                end
                box:Destroy()
                updateLayout()
            end)
        end
    end)
end

local function playHitSound()
    if not ConfigTable.Ragebot.HitSound then return end
    local soundId = soundIds[ConfigTable.Ragebot.SelectedHitSound] or soundIds["叮咚鸡"]
    local sound = Instance.new("Sound")
    sound.SoundId = soundId
    sound.Volume = 0.75
    sound.Parent = Workspace
    sound:Play()
    Debris:AddItem(sound, 0.75)
end

local function createTracer(startPos, endPos)
    if not ConfigTable.Ragebot.Tracers then return end
    
    local tracerModel = Instance.new("Model")
    tracerModel.Name = "TracerBeam"
    
    local beam = Instance.new("Beam")
    beam.Color = ColorSequence.new(ConfigTable.Ragebot.TracerColor)
    beam.Width0 = ConfigTable.Ragebot.TracerWidth
    beam.Width1 = ConfigTable.Ragebot.TracerWidth
    beam.Texture = tracerTextures[ConfigTable.Ragebot.TracerTexture] or tracerTextures["Default"]
    beam.TextureSpeed = 1
    beam.Brightness = 2
    beam.LightEmission = 2
    beam.FaceCamera = true
    
    local a0 = Instance.new("Attachment")
    local a1 = Instance.new("Attachment")
    a0.WorldPosition = startPos
    a1.WorldPosition = endPos
    
    beam.Attachment0 = a0
    beam.Attachment1 = a1
    beam.Parent = tracerModel
    a0.Parent = tracerModel
    a1.Parent = tracerModel
    tracerModel.Parent = Workspace
    
    local tween = TweenService:Create(beam, TweenInfo.new(ConfigTable.Ragebot.TracerLifetime, Enum.EasingStyle.Linear), {Brightness = 0})
    tween:Play()
    Debris:AddItem(tracerModel, ConfigTable.Ragebot.TracerLifetime)
end

local function RandomString(length)
    local charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
    local result = {}
    for i = 1, length do 
        local rand = math.random(1, #charset)
        result[i] = charset:sub(rand, rand)
    end
    return table.concat(result)
end

local function shootAtTarget(targetHead)
    if not targetHead then return false end
    local localHead = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Head")
    if not localHead then return false end
    
    local tool = getCurrentTool()
    if not tool then return false end
    
    local values = tool:FindFirstChild("Values")
    local hitMarker = tool:FindFirstChild("Hitmarker")
    if not values or not hitMarker then return false end
    
    local ammo = values:FindFirstChild("SERVER_Ammo")
    if ammo.Value <= 0 then 
        autoReload()
        return false 
    end
    
    local bestShootPos, bestHitPos = wallbangLogic()
    if not bestShootPos or not bestHitPos then return false end
    
    local hitPosition = bestHitPos
    if ConfigTable.Ragebot.Prediction then 
        local velocity = targetHead.Velocity or Vector3.new(0,0,0)
        hitPosition = hitPosition + velocity * ConfigTable.Ragebot.PredictionAmount 
    end
    
    local hitDirection = (hitPosition - bestShootPos).Unit
    local randomKey = RandomString(30) .. "0"
    
    local events = ReplicatedStorage:FindFirstChild("Events")
    if not events then return false end
    local GNX_S = events:FindFirstChild("GNX_S")
    local ZFKLF__H = events:FindFirstChild("ZFKLF__H")
    if not GNX_S or not ZFKLF__H then return false end
    
    local args1 = {tick(), randomKey, tool, "FDS9I83", bestShootPos, {hitDirection}, false}
    local args2 = {"🧈", tool, randomKey, 1, targetHead, hitPosition, hitDirection}
    
    local targetPlayer = Players:GetPlayerFromCharacter(targetHead.Parent)
    if targetPlayer then 
        task.spawn(function()
            createHitNotification(tool.Name, (bestShootPos - localHead.Position).Magnitude, targetPlayer.Name) 
            playHitSound()
        end)
    end
    
    GNX_S:FireServer(unpack(args1))
    ZFKLF__H:FireServer(unpack(args2))
    hitMarker:Fire(targetHead)
    
    task.spawn(function()
        createTracer(bestShootPos, hitPosition)
    end)
    return true
end

RunService.Heartbeat:Connect(function()
    if not ConfigTable.Ragebot.Enabled then return end
    
    local char = LocalPlayer.Character
    if not char or not char:FindFirstChild("Head") then return end
    
    local target = getClosestTarget()
    if not target then return end
    
    local currentTool = getCurrentTool()
    local isSpecial = currentTool and (currentTool.Name == "TEC-9" or currentTool.Name == "Beretta")
    local fireRate = 2.5
    
    if isSpecial then
        fireRate = ConfigTable.Ragebot.RapidFire and 9e14 or ConfigTable.Ragebot.FireRate
    else
        for _, v in pairs(getgc(true)) do
            if type(v) == "table" and rawget(v, "FireRate") and rawget(v, "Damage") and rawget(v, "MagSize") then
                fireRate = rawget(v, "FireRate")
                break
            end
        end
    end
    
    local currentTime = tick()
    if isSpecial and ConfigTable.Ragebot.RapidFire then
        shootAtTarget(target)
    elseif currentTime - lastShotTime >= 1 / fireRate then
        if shootAtTarget(target) then
            lastShotTime = currentTime
        end
    end
end)

