local function getPlayerNames()
    local names = {}
    local allPlayers = Players:GetPlayers()
    for i = 1, #allPlayers do
        local p = allPlayers[i]
        if p ~= LocalPlayer then
            table.insert(names, p.Name)
        end
    end
    return #names > 0 and names or {"无玩家"}
end

local function forceRefreshUI()
    local pList = getPlayerNames()
    local wList = #Whitelist > 0 and Whitelist or {"无数据"}
    local tList = #TargetList > 0 and TargetList or {"无数据"}
    
    if playerDropdown then
        if playerDropdown.Refresh then
            playerDropdown:Refresh(pList, true)
        elseif playerDropdown.SetValues then
            playerDropdown:SetValues(pList)
        end
    end

    if whitelistDropdown then
        if whitelistDropdown.Refresh then
            whitelistDropdown:Refresh(wList, true)
        elseif whitelistDropdown.SetValues then
            whitelistDropdown:SetValues(wList)
        end
    end

    if targetDropdown then
        if targetDropdown.Refresh then
            targetDropdown:Refresh(tList, true)
        elseif targetDropdown.SetValues then
            targetDropdown:SetValues(tList)
        end
    end
end

