local AttackInputRemote = CombatRemote:WaitForChild("AttackInput")

local Config = {
    AutoBlock = false,
    AutoBlockRange = 20,
    AutoBlockDelay = 0.01
}

local BlockAnimations = {}
local GlobalAttacksFolder = ReplicatedStorage.Animations.Attacks.Global.M1
for _, anim in ipairs(GlobalAttacksFolder:GetDescendants()) do
    if anim:IsA("Animation") then
        BlockAnimations[anim.AnimationId] = true
    end
end

local BlockHeld = false
local function ReleaseBlock()
    if BlockHeld then
        AttackInputRemote:FireServer("Block", false)
        BlockHeld = false
    end
end

local function CheckForAttacks()
    if not Character then return false end
    local myRoot = Character:FindFirstChild("HumanoidRootPart")
    if not myRoot then return false end

    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LocalPlayer and plr.Character then
            local targetRoot = plr.Character:FindFirstChild("HumanoidRootPart")
            if targetRoot and (myRoot.Position - targetRoot.Position).Magnitude < Config.AutoBlockRange then
                local humanoid = plr.Character:FindFirstChildOfClass("Humanoid")
                if humanoid then
                    for _, track in ipairs(humanoid:GetPlayingAnimationTracks()) do
                        if BlockAnimations[track.Animation.AnimationId] then
                            return true
                        end
                    end
                end
            end
        end
    end
    return false
end

RunService.Heartbeat:Connect(function()
    if Config.AutoBlock then
        local incomingAttack = CheckForAttacks()
        if incomingAttack and not BlockHeld then
            BlockHeld = true
            local pingDelay = Config.AutoBlockDelay + StatsService.Network.ServerStatsItem["Data Ping"]:GetValue() / 1000 / 2
            task.delay(pingDelay, function()
                if BlockHeld then
                    AttackInputRemote:FireServer("Block", true)
                end
            end)
        elseif not incomingAttack and BlockHeld then
            ReleaseBlock()
        end
    else
        ReleaseBlock()
    end
end)

