local LockTab = Window:Tab({  
    Title = "锁人",  
    Icon = "crosshair",  
    Locked = false,
})
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LocalPlayer = Players.LocalPlayer

local v3new = Vector3.new
local cfnew = CFrame.new
local mathcos = math.cos
local mathsin = math.sin
local tableinsert = table.insert
local pairs = pairs

local BEHIND_DISTANCE = 5
local CIRCLE_RADIUS = 6
local CIRCLE_SPEED = 13

local followEnabled = false
local circleEnabled = false
local lookEnabled = false
local selectedTargetName = nil

local circleAngle = 0
local mainConnection = nil

local function getRoot(player)
    if player and player.Character then
        return player.Character:FindFirstChild("HumanoidRootPart")
    end
end

local function getPlayerByName(name)
    for _, p in pairs(Players:GetPlayers()) do
        if p.Name == name then
            return p
        end
    end
end

local function getPlayerNames()
    local names = {}
    for _, p in pairs(Players:GetPlayers()) do
        if p ~= LocalPlayer then
            tableinsert(names, p.Name)
        end
    end
    return names
end

local function updateLoop(dt)
    if not selectedTargetName then return end
    
    local target = getPlayerByName(selectedTargetName)
    local targetRoot = getRoot(target)
    local myRoot = getRoot(LocalPlayer)
    
    if not targetRoot or not myRoot then return end
    
    local targetPos = targetRoot.Position
    local finalPos = nil
    
    if circleEnabled then
        circleAngle = circleAngle + (CIRCLE_SPEED * dt)
        local x = mathcos(circleAngle) * CIRCLE_RADIUS
        local z = mathsin(circleAngle) * CIRCLE_RADIUS
        finalPos = targetPos + v3new(x, 0, z)
    elseif followEnabled then
        local offset = targetRoot.CFrame.LookVector * BEHIND_DISTANCE
        finalPos = targetPos - offset
    end
    
    if finalPos then
        if lookEnabled then
            myRoot.CFrame = cfnew(finalPos, v3new(targetPos.X, finalPos.Y, targetPos.Z))
        else
            myRoot.CFrame = cfnew(finalPos) * myRoot.CFrame.Rotation
        end
    elseif lookEnabled then
        local myPos = myRoot.Position
        myRoot.CFrame = cfnew(myPos, v3new(targetPos.X, myPos.Y, targetPos.Z))
    end
end

local function toggleConnection()
    if followEnabled or circleEnabled or lookEnabled then
        if not mainConnection then
            mainConnection = RunService.RenderStepped:Connect(updateLoop)
        end
    else
        if mainConnection then
            mainConnection:Disconnect()
            mainConnection = nil
        end
    end
end

local playerDropdown = LockTab:Dropdown({
    Title = "选择目标玩家",
    Multi = false,
    AllowNone = true,
    Value = nil,
    Values = getPlayerNames(),
    Callback = function(name)
        selectedTargetName = name
    end
})

