        selectedTargetName = nil
        local newNames = getPlayerNames()
        if playerDropdown then
            if playerDropdown.SetValues then
                playerDropdown:SetValues(newNames)
            elseif playerDropdown.Refresh then
                playerDropdown:Refresh(newNames, true)
            end
            if playerDropdown.SetValue then
                playerDropdown:SetValue(nil)
            end
        end
    end
})

LockTab:Toggle({
    Title = "锁背",
    Value = false,
    Callback = function(state)
        followEnabled = state
        if state then circleEnabled = false end
        toggleConnection()
    end
})

LockTab:Toggle({
    Title = "转圈",
