Esp:Toggle({
    Title = "透视实验门",
    Desc = "透视",
    Value = false,
    Callback = function(state)        
        local con
        if state then
            GetEsp = false
            
            con = RunService.Heartbeat:Connect(function()
                if GetEsp then
                    return
                end
                for _, r in ipairs(workspace.Abnormalities:GetChildren()) do
                    local d = r:FindFirstChild("AbnormalityRoom") and r.AbnormalityRoom:FindFirstChild("AbnormalityDoorModel")
                    if d then
                        if not d:FindFirstChild("Esp") then
                            local h = Instance.new("Highlight")
                            h.Name = "Esp"
                            h.Parent = d
                            h.FillColor = Color3.new(0, 1, 1)
                            h.FillTransparency = Esp.FillTrans
                            h.OutlineColor = Color3.new(1, 1, 1)
                            h.OutlineTransparency = Esp.OrantTran

                            local bg = Instance.new("BillboardGui")
                            bg.Name = "DoorGui"
                            bg.Parent = d
                            bg.Size = UDim2.new(0, 100, 0, 40)
                            bg.AlwaysOnTop = true
                            bg.StudsOffset = Vector3.new(0, 3, 0)

                            local t = Instance.new("TextLabel")
                            t.Parent = bg
                            t.Size = UDim2.new(1, 0, 1, 0)
                            t.BackgroundTransparency = 1
                            t.TextColor3 = Color3.new(0, 1, 1)
                            t.TextSize = 10

                            local s = Instance.new("UIStroke")
                            s.Parent = t
                            s.Color = Color3.new(0, 0, 0)
                            s.Thickness = 0.5
                        end
                        local dist = (HumanoidRootPart.Position - d.DoorHitBox.Position).Magnitude
                        d.DoorGui.TextLabel.Text = "实验门[" .. string.format("%.0f", dist) .. "m]"
                    end
                end
            end)
        else
            GetEsp = true
            if con then con:Disconnect() end
            for _, r in ipairs(workspace.Abnormalities:GetChildren()) do
                local d = r:FindFirstChild("AbnormalityRoom") and r.AbnormalityRoom:FindFirstChild("AbnormalityDoorModel")
                if d then
                    if d:FindFirstChild("Esp") then d.Esp:Destroy() end
                    if d:FindFirstChild("DoorGui") then d.DoorGui:Destroy() end
                end
            end
        end
    end
})


