local function TeleportToShop(shopName)
    if Teleporting then 
        Window:Notify({
            Title = "传送",
            Content = "正在传送中，请稍候...",
            Duration = 2
        })
        return 
    end
    
    local position = ShopLocations[shopName]
    if not position then
        Window:Notify({
            Title = "错误",
            Content = "未知的商店位置: " .. tostring(shopName),
            Duration = 3
        })
        return
    end
    
    local character = LocalPlayer.Character
    if not character then
        Window:Notify({
            Title = "错误",
            Content = "角色不存在",
            Duration = 3
        })
        return
    end
    
    local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
    if not humanoidRootPart then
        Window:Notify({
            Title = "错误",
            Content = "未找到 HumanoidRootPart",
            Duration = 3
        })
        return
    end
    
    Teleporting = true
    Window:Notify({
        Title = "传送",
        Content = "正在传送到 " .. shopName,
        Duration = 2
    })
    
    local targetCFrame = CFrame.new(position)
    local distance = (position - humanoidRootPart.Position).Magnitude
    
    if distance < InstaTeleportDistance then
        humanoidRootPart.CFrame = targetCFrame
        Teleporting = false
        Window:Notify({
            Title = "传送完成",
            Content = "已到达 " .. shopName,
            Duration = 2
        })
        return
    end
    
    local tweenInfo = TweenInfo.new(distance / TeleportSpeed, Enum.EasingStyle.Linear)
    local tween = TweenService:Create(humanoidRootPart, tweenInfo, {CFrame = targetCFrame})
    
    tween:Play()
    tween.Completed:Connect(function()
        Teleporting = false
        Window:Notify({
            Title = "传送完成",
            Content = "已到达 " .. shopName,
            Duration = 2
        })
    end)
end

local function TeleportToLocation(locationName)
    if ShopLocations[locationName] then
        TeleportToShop(locationName)
    else
        Window:Notify({
            Title = "错误",
            Content = "位置不存在: " .. tostring(locationName),
            Duration = 3
        })
    end
end

local function StartAutoMine()
    if MineFarmRunning then return end
    
    MineFarmRunning = true
    task.spawn(function()
        while MineFarmRunning do
            task.wait(0.1)
            
            local character = LocalPlayer.Character
            if not character then
                task.wait(1)
                continue
            end
            
            local HRP = character:FindFirstChild("HumanoidRootPart")
            if not HRP then
                task.wait(1)
                continue
            end
            
            local Target = nil
            local LastDist = math.huge
            
            local rocksFolder = workspace:FindFirstChild("Rocks")
            if rocksFolder then
                for _, area in pairs(rocksFolder:GetChildren()) do
                    if not area:IsA("Folder") then continue end
                    
                    local areaSelected = false
                    for _, selectedArea in ipairs(SelectedAreas) do
                        if string.find(area.Name, selectedArea, 1, true) then
                            areaSelected = true
                            break
                        end
                    end
                    
                    if not areaSelected then continue end
                    
                    for _, spawnLoc in pairs(area:GetChildren()) do
                        for _, rock in pairs(spawnLoc:GetChildren()) do
                            if not rock:IsA("Model") then continue end
                            
                            local Health = rock:GetAttribute("Health")
                            local MaxHealth = rock:GetAttribute("MaxHealth")
                            local LastHitPlayer = rock:GetAttribute("LastHitPlayer")
                            
                            if Health and MaxHealth and Health > 0 then
                                local isAvailable = (LastHitPlayer == LocalPlayer.Name) or (Health == MaxHealth)
                                
                                if isAvailable then
                   
                                    local rockSelected = false
                                    for _, oreName in ipairs(SelectedOres) do
                                        if string.find(rock.Name, oreName, 1, true) then
                                            rockSelected = true
                                            break
                                        end
                                    end
                                    
                                    if rockSelected then
                                        local hitbox = rock:FindFirstChild("Hitbox")
                                        if hitbox then
                                            local Dist = (hitbox.Position - HRP.Position).Magnitude
                                            if Dist < LastDist then
                                                LastDist = Dist
                                                Target = rock
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            
            if Target and not Teleporting then
                local Hitbox = Target:FindFirstChild("Hitbox")
                if Hitbox then
                    local Continue = true
                    local CurrentHealth = Target:GetAttribute("Health")
                    
                    while CurrentHealth and Target and Target.Parent and CurrentHealth > 0 and MineFarmRunning and Continue and not Teleporting do
                        local Pos = Hitbox.CFrame + Vector3.new(0, MineHeight, 0)
                        local NewCFrame = CFrame.new(Pos.Position, Hitbox.Position)
                        
                        local distanceToHitbox = (Hitbox.Position - HRP.Position).Magnitude
                        
                        if distanceToHitbox < InstaTeleportDistance then
                            HRP.CFrame = NewCFrame
                        else
                            local TPTween = TweenService:Create(HRP, TweenInfo.new(distanceToHitbox / TeleportSpeed, Enum.EasingStyle.Linear), {CFrame = NewCFrame})
                            TPTween:Play()
                            local success, err = pcall(function()
                                TPTween.Completed:Wait()
                            end)
                        end
                        
                        HRP.Anchored = AnchorCharacter
                        
                        local toolService = game:GetService("ReplicatedStorage"):FindFirstChild("Shared")
                        if toolService then
                            local Knit = toolService:FindFirstChild("Packages")
                            if Knit and Knit:FindFirstChild("Knit") then
                                local ToolService = Knit.Knit.Services.ToolService
                                if ToolService and ToolService:FindFirstChild("RF") then
                                    local ToolActivated = ToolService.RF:FindFirstChild("ToolActivated")
                                    if ToolActivated then
                                        pcall(function()
                                            ToolActivated:InvokeServer("Pickaxe")
                                        end)
                                    end
                                end
                            end
                        end
                        
                        task.wait(0.5)
                        CurrentHealth = Target:GetAttribute("Health")
                        local MaxHealth = Target:GetAttribute("MaxHealth")
                        local LastHitPlayer = Target:GetAttribute("LastHitPlayer")
                        
                        if CurrentHealth and MaxHealth and CurrentHealth < MaxHealth and LastHitPlayer ~= LocalPlayer.Name then 
                            Continue = false 
                        end
                        
                        if Hitbox and HRP and (Hitbox.Position - HRP.Position).Magnitude > 15 then 
                            Continue = false 
                        end
                    end
                    
                    HRP.Anchored = false
                end
            else
                task.wait(1)
            end
        end
    end)
end

local function StartAutoSell()
    if AutoSellRunning then return end
    
    AutoSellRunning = true
    task.spawn(function()
        while AutoSellRunning do
            task.wait(AutoSellDelay)
            
            if Teleporting then
                task.wait(1)
                continue
            end
            
            local character = LocalPlayer.Character
            if not character then
                task.wait(1)
                continue
            end
            
            local HRP = character:FindFirstChild("HumanoidRootPart")
            if not HRP then
                task.wait(1)
                continue
            end
            
            local proximityFolder = workspace:FindFirstChild("Proximity")
            if not proximityFolder then
                task.wait(1)
                continue
            end
            
            local NPC = proximityFolder:FindFirstChild("Greedy Cey")
            if not NPC then
                Window:Notify({
                    Title = "自动出售",
                    Content = "未找到出售NPC",
                    Duration = 3
                })
                task.wait(5)
                continue
            end
            
            local NpcHRP = NPC:FindFirstChild("HumanoidRootPart")
            if not NpcHRP then
                task.wait(1)
                continue
            end
            
            Teleporting = true
            
            local NewCFrame = NpcHRP.CFrame
            local distance = (NpcHRP.Position - HRP.Position).Magnitude
            
            if distance < InstaTeleportDistance then
                HRP.CFrame = NewCFrame
            else
                local tweenInfo = TweenInfo.new(distance / TeleportSpeed, Enum.EasingStyle.Linear)
                local tween = TweenService:Create(HRP, tweenInfo, {CFrame = NewCFrame})
                tween:Play()
                local success, err = pcall(function()
                    tween.Completed:Wait()
                end)
            end
            
            task.wait(1)
            
            local replicatedStorage = game:GetService("ReplicatedStorage")
            local shared = replicatedStorage:FindFirstChild("Shared")
            if shared then
                local packages = shared:FindFirstChild("Packages")
                if packages then
                    local knit = packages:FindFirstChild("Knit")
                    if knit then
                        local services = knit:FindFirstChild("Services")
                        if services then
                            local ProximityService = services:FindFirstChild("ProximityService")
                            local DialogueService = services:FindFirstChild("DialogueService")
                            
                            if ProximityService and ProximityService:FindFirstChild("RF") then
                                local forceDialogue = ProximityService.RF:FindFirstChild("ForceDialogue")
                                if forceDialogue then
                                    pcall(function()
                                        forceDialogue:InvokeServer(NPC, "SellConfirmMisc")
                                    end)
                                end
                            end
                            
                            if DialogueService and DialogueService:FindFirstChild("RF") then
                                local runCommand = DialogueService.RF:FindFirstChild("RunCommand")
                                if runCommand then
                                    task.wait(0.5)
                                    pcall(function()
                                        runCommand:InvokeServer("SellConfirm", {})
                                    end)
                                end
                            end
                        end
                    end
                end
            end
            
            Teleporting = false
            Window:Notify({
                Title = "自动出售",
                Content = "出售完成",
                Duration = 2
            })
        end
    end)
end


