local function getDeviceType()
    local UserInputService = game:GetService("UserInputService")
    if UserInputService.TouchEnabled then
        if UserInputService.KeyboardEnabled then
            return "tablet"
        else
            return "mobile"
        end
    else
        return "pc"
    end
end

