local DoorConnect = false
TabHandles.Esp:Toggle({
    Title = "door esp",
    Desc = "esp",
    Value = false,
    Callback = function(state)
        if state then
            if DoorConnect then
                DoorConnect:Disconnect()
                DoorConnect = nil
            end
            DoorConnect = RunService.Heartbeat:Connect(function()
                for _, v in pairs(workspace.GameplayFolder:GetChildren()) do
                    for _, i in pairs(v:GetDescendants()) do
                        if i.Name == 'NormalDoor' and i:IsA('Model') then
                            local distance = (game.Players.LocalPlayer.Character:FindFirstChild('HumanoidRootPart').Position - i:GetPivot().Position).Magnitude
                            local m = 'door' .. '[' .. string.format('%.0f', distance) .. 'm]'
                            
                            if not i:FindFirstChild('EspDoor') then
                                local h = Instance.new('Highlight', i)
                                h.FillTransparency = EspList.F
                                h.OutlineTransparency = EspList.O
                                h.FillColor = Color3.fromRGB(51, 255, 241)
                                h.Name = 'EspDoor'
                                local b = Instance.new('BillboardGui', i)
                                b.AlwaysOnTop = true
                                b.Size = UDim2.new(0, 500, 0, 200)
                                b.Name = 'EspDoorBili'
                                local t = Instance.new('TextLabel', b)
                                t.Size = UDim2.new(0, 500, 0, 200)
                                t.TextSize = EspList.T
                                t.TextColor3 = Color3.fromRGB(51, 255, 241)
                                t.Name = 'EspDoorText'
                                t.BackgroundTransparency = 1
                                t.Text = m
                                local ts = Instance.new('UIStroke', t)
                                ts.Thickness = 1
                            else
                                local espBili = i:FindFirstChild('EspDoorBili')
                                if espBili then
                                    local textLabel = espBili:FindFirstChild('EspDoorText')
                                    if textLabel then
                                        textLabel.Text = m
                                    end
                                end
                            end
                        end
                    end
                end
            end)
        else
            for _, v in pairs(workspace:GetDescendants()) do
                if v.Name == 'EspDoor' or v.Name == 'EspDoorBili' or v.Name == 'EspDoorText' then
                    v:Destroy()
                end
            end
        end
    end
})

