    Title = "anti fall damage",
    Value = false,
    Callback = function(state)
        if state then
            coon = game:GetService("RunService").RenderStepped:Connect(function()
                if workspace:Raycast(game.Players.LocalPlayer.Character.HumanoidRootPart.Position, Vector3.new(0, -20, 0)).Instance ~= nil and 
                   game.Players.LocalPlayer.Character.HumanoidRootPart.Velocity.Y < -30 then 
                    game.Players.LocalPlayer.Character.HumanoidRootPart.Velocity = Vector3.new(0,0,0)
                end
            end)
        else
            if coon then coon:Disconnect() end
        end
    end
})

PlayerSection:Toggle({
    Title = "anti ragdoll",
    Value = false,
    Callback = function(state)
        antiragdoll = state
        if antiragdoll then
            coon2 = game.Players.LocalPlayer.Character.Humanoid:GetPropertyChangedSignal("Health"):Connect(function()
                game.Players.LocalPlayer.Character.Humanoid.Health = 100
            end)
        else
            if coon2 then coon2:Disconnect() end
        end
    end
})

PlayerSection:Toggle({
    Title = "infinite stamina",
    Callback = function(state)
        if state then
            local func 
            for i,v in pairs(getgc(true)) do
                if type(v) == "function" and getinfo(v).name == "setStamina" then
                    func = v
                end
            end
            if func then
                hookfunction(func,function(...)
                    local args = {...}
                    return args[1],math.huge
                end)
            end
        else
            local func 
            for i,v in pairs(getgc(true)) do
                if type(v) == "function" and getinfo(v).name == "setStamina" then
                    func = v
                end
            end
            if func then
                restorefunction(func)
            end
        end
    end
})

local TeamsService = game:GetService("Teams")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LocalPlayer = Players.LocalPlayer
local Camera = workspace.CurrentCamera

local teams = {}
for _, v in pairs(TeamsService:GetChildren()) do
    table.insert(teams, v.Name)
end

local enemy = nil
local aimbot = false
local aimbotConnection = nil

AimbotSection:Dropdown({
    Title = "Select Enemy Team",
    Values = teams,
    Callback = function(state) 
        enemy = state
    end
})

AimbotSection:Toggle({
    Title = "Aimbot",
    Value = false,
    Callback = function(state)
        aimbot = state
        
        if aimbot then
            if aimbotConnection then aimbotConnection:Disconnect() end
            
            aimbotConnection = RunService.RenderStepped:Connect(function()
                if not aimbot then 
                    if aimbotConnection then aimbotConnection:Disconnect() end
                    return 
                end

                local char = LocalPlayer.Character
                local tool = char and char:FindFirstChildOfClass("Tool")
                
                if tool and enemy then
                    local target = nil
                    local shortestDistance = math.huge

                    for _, player in pairs(Players:GetPlayers()) do
                        if player ~= LocalPlayer and player.Team and player.Team.Name == enemy then
                            if player.Character and player.Character:FindFirstChild("Head") and player.Character:FindFirstChild("Humanoid") and player.Character.Humanoid.Health > 0 then
                                local pos, onScreen = Camera:WorldToViewportPoint(player.Character.Head.Position)
                                if onScreen then
                                    local magnitude = (Vector2.new(pos.X, pos.Y) - Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2)).Magnitude
                                    if magnitude < shortestDistance then
                                        shortestDistance = magnitude
                                        target = player
                                    end
                                end
                            end
                        end
                    end

                    if target then
                        Camera.CFrame = CFrame.new(Camera.CFrame.Position, target.Character.Head.Position)
                    end
                end
            end)
        else
            if aimbotConnection then
                aimbotConnection:Disconnect()
                aimbotConnection = nil
            end
        end
    end
})

end

