local ESP_Objects = {}

local function CreateESP(player)
    if player == game.Players.LocalPlayer then return end
    
    local highlight = Instance.new("Highlight")
    highlight.Name = "ESP_Highlight"
    highlight.Parent = game.CoreGui
    highlight.Adornee = player.Character
    highlight.FillTransparency = 0.5
    highlight.OutlineTransparency = 0
    
    local function UpdateColor()
        local team = player.Team and player.Team.Name or ""
        if team:find("Police") or team:find("Officer") or team:find("Sheriff") then
            highlight.FillColor = Color3.fromRGB(0, 120, 255)
            highlight.OutlineColor = Color3.fromRGB(0, 120, 255)
        elseif team:find("Criminal") or team:find("Prisoner") then
            highlight.FillColor = Color3.fromRGB(255, 255, 0)
            highlight.OutlineColor = Color3.fromRGB(255, 255, 0)
        else
            highlight.FillColor = Color3.fromRGB(0, 255, 0)
            highlight.OutlineColor = Color3.fromRGB(0, 255, 0)
        end
    end

    UpdateColor()
    player:GetPropertyChangedSignal("Team"):Connect(UpdateColor)
    
    player.CharacterAdded:Connect(function(char)
        highlight.Adornee = char
        UpdateColor()
    end)

    ESP_Objects[player] = highlight
end

PlayerSection:Toggle({
    Title = "透视",
    Value = false,
    Callback = function(state)
        _G.ESP_Enabled = state
        if state then
            for _, v in pairs(game.Players:GetPlayers()) do
                CreateESP(v)
            end
            game.Players.PlayerAdded:Connect(CreateESP)
        else
            for _, v in pairs(ESP_Objects) do
                v:Destroy()
            end
            table.clear(ESP_Objects)
        end
    end
})

local TeamsService = game:GetService("Teams")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LocalPlayer = Players.LocalPlayer
local Camera = workspace.CurrentCamera

local teams = {}
for _, v in pairs(TeamsService:GetChildren()) do
    table.insert(teams, v.Name)
end

local enemy = nil
local aimbot = false
local aimbotConnection = nil

AimbotSection:Dropdown({
    Title = "选择敌方队伍",
    Values = teams,
    Callback = function(state) 
        enemy = state
    end
})

AimbotSection:Toggle({
    Title = "自瞄",
    Value = false,
    Callback = function(state)
        aimbot = state
        
        if aimbot then
            aimbotConnection = RunService.RenderStepped:Connect(function()
                if not aimbot then 
                    if aimbotConnection then aimbotConnection:Disconnect() end
                    return 
                end

                local tool = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Tool")
                if tool and enemy then
                    local target = nil
                    local shortestDistance = math.huge

                    for _, player in pairs(Players:GetPlayers()) do
                        if player ~= LocalPlayer and player.Team and player.Team.Name == enemy then
                            if player.Character and player.Character:FindFirstChild("Head") and player.Character:FindFirstChild("Humanoid") and player.Character.Humanoid.Health > 0 then
                                local pos, onScreen = Camera:WorldToViewportPoint(player.Character.Head.Position)
                                if onScreen then
                                    local magnitude = (Vector2.new(pos.X, pos.Y) - Vector2.new(Camera.ViewportSize.X / 2, Camera.ViewportSize.Y / 2)).Magnitude
                                    if magnitude < shortestDistance then
                                        shortestDistance = magnitude
                                        target = player
                                    end
                                end
                            end
                        end
                    end

                    if target then
                        Camera.CFrame = CFrame.new(Camera.CFrame.Position, target.Character.Head.Position)
                    end
                end
            end)
        else
            if aimbotConnection then
                aimbotConnection:Disconnect()
                aimbotConnection = nil
            end
        end
    end
})

end
local function ylxx()
Window:Divider()
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local mt = getrawmetatable(game)
local oldNamecall = mt.__namecall
local fallImmuneEnabled = false

local gunStatsModule = require(ReplicatedStorage.GunScripts.GunStats)
local backup = {}
for i, stat in pairs(gunStatsModule) do
    backup[i] = {}
    for k, v in pairs(stat) do
        backup[i][k] = v
    end
end

local function restoreStats()
    for i, stat in pairs(gunStatsModule) do
        for k, v in pairs(backup[i]) do
            stat[k] = v
        end
    end
end
local Tab = Window:Tab({  
    Title = "功能",  
    Icon = "house",  
    Locked = false,
})
Tab:Toggle({
    Title = "免疫摔落伤害",
    Value = false,
    Callback = function(state)
        fallImmuneEnabled = state
        setreadonly(mt, false)
        mt.__namecall = newcclosure(function(remote, ...)
            if fallImmuneEnabled and getnamecallmethod() == "FireServer" and remote.Name == "ChangeCharacter" then
                local args = {...}
                if args[1] == "Damage" then
                    return nil
                end
            end
            return oldNamecall(remote, ...)
        end)
        setreadonly(mt, true)
    end
})

Tab:Toggle({
    Title = "无后座",
    Value = false,
    Callback = function(state)
        restoreStats()
        if state then
            for _, gunStat in pairs(gunStatsModule) do
                if gunStat.FanFire ~= nil then gunStat.FanFire = true end
                if gunStat.camShakeResist ~= nil then gunStat.camShakeResist = 0 end
                if gunStat.prepTime ~= nil then gunStat.prepTime = 0 end
                if gunStat.equipTime ~= nil then gunStat.equipTime = 0 end
                if gunStat.Spread ~= nil then gunStat.Spread = 0 end
                if gunStat.InstantFireAnimation ~= nil then gunStat.InstantFireAnimation = true end
            end
        end
    end
})

Tab:Toggle({
    Title = "秒换弹",
    Value = false,
    Callback = function(state)
        restoreStats()
        if state then
            for _, gunStat in pairs(gunStatsModule) do
                if gunStat.FanFire ~= nil then gunStat.FanFire = true end
                if gunStat.prepTime ~= nil then gunStat.prepTime = 0 end
                if gunStat.equipTime ~= nil then gunStat.equipTime = 0 end
                if gunStat.camShakeResist ~= nil then gunStat.camShakeResist = 0 end
                if gunStat.ReloadAnimationSpeed ~= nil then gunStat.ReloadAnimationSpeed = 10 end
                if gunStat.ReloadSpeed ~= nil then gunStat.ReloadSpeed = 0 end
                if gunStat.Spread ~= nil then gunStat.Spread = 0 end
                if gunStat.InstantFireAnimation ~= nil then gunStat.InstantFireAnimation = true end
            end
        end
    end
})

Tab:Toggle({
    Title = "子弹无分散",
    Value = false,
    Callback = function(state)
        restoreStats()
        if state then
            for _, gunStat in pairs(gunStatsModule) do
                if gunStat.FanFire ~= nil then gunStat.FanFire = true end
                if gunStat.prepTime ~= nil then gunStat.prepTime = 0 end
                if gunStat.equipTime ~= nil then gunStat.equipTime = 0 end
                if gunStat.camShakeResist ~= nil then gunStat.camShakeResist = 0 end
                if gunStat.ReloadAnimationSpeed ~= nil then gunStat.ReloadAnimationSpeed = 10 end
                if gunStat.ReloadSpeed ~= nil then gunStat.ReloadSpeed = 0 end
                if gunStat.Spread ~= nil then gunStat.Spread = 0 end
                if gunStat.HipFireAccuracy ~= nil then gunStat.HipFireAccuracy = 0 end
                if gunStat.ZoomAccuracy ~= nil then gunStat.ZoomAccuracy = 0 end
                if gunStat.InstantFireAnimation ~= nil then gunStat.InstantFireAnimation = true end
            end
        end
    end
})
