ListContainer.Parent = ScreenGui

local UIListLayout = Instance.new("UIListLayout")
UIListLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
UIListLayout.VerticalAlignment = Enum.VerticalAlignment.Top
UIListLayout.SortOrder = Enum.SortOrder.LayoutOrder
UIListLayout.Padding = UDim.new(0, 4)
UIListLayout.Parent = ListContainer

local activeModules = {}
local enabledFeatures = {}
local arrayEnabled = false

local function CreateModuleLabel(name)
    local Holder = Instance.new("Frame")
    Holder.Name = name .. "_Holder"
    Holder.Size = UDim2.new(0, 0, 0, 24)
    Holder.BackgroundTransparency = 1

    local Frame = Instance.new("Frame")
    Frame.Size = UDim2.new(1, 0, 1, 0)
    Frame.Position = UDim2.new(1, 50, 0, 0)
    Frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    Frame.BackgroundTransparency = 0.5
    Frame.BorderSizePixel = 0
    Frame.ClipsDescendants = true
    Frame.Parent = Holder

    local Corner = Instance.new("UICorner")
    Corner.CornerRadius = UDim.new(0, 4)
    Corner.Parent = Frame

    local TextLabel = Instance.new("TextLabel")
    TextLabel.Size = UDim2.new(1, -10, 1, 0)
    TextLabel.Position = UDim2.new(0, 5, 0, 0)
    TextLabel.BackgroundTransparency = 1
    TextLabel.RichText = true
    TextLabel.Font = Enum.Font.GothamMedium
    TextLabel.TextSize = 14
    TextLabel.TextXAlignment = Enum.TextXAlignment.Right
    TextLabel.TextColor3 = Color3.new(1, 1, 1)
    TextLabel.Parent = Frame

    local SideBar = Instance.new("Frame")
    SideBar.Size = UDim2.new(0, 3, 1, 0)
    SideBar.Position = UDim2.new(1, -3, 0, 0)
    SideBar.BorderSizePixel = 0
    SideBar.Parent = Frame

    local SideCorner = Instance.new("UICorner")
    SideCorner.CornerRadius = UDim.new(0, 2)
    SideCorner.Parent = SideBar

    return Holder, Frame, TextLabel, SideBar
end

local function UpdateList()
    local sorted = {}
    for _, data in pairs(activeModules) do
        sorted[#sorted + 1] = data
    end
    table.sort(sorted, function(a, b)
        return a.TextLabel.TextBounds.X > b.TextLabel.TextBounds.X
    end)
    for i, data in ipairs(sorted) do
        data.Holder.LayoutOrder = i
    end
end

local function SlideIn(frame)
    TweenService:Create(frame, TweenInfo.new(0.45, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Position = UDim2.new(0, 0, 0, 0)
    }):Play()
end

local function SlideOut(frame)
    TweenService:Create(frame, TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
        Position = UDim2.new(1, 50, 0, 0)
    }):Play()
end

local function RenderFeatureModule(name, value)
    local displayText = name
    if value then
        displayText = name .. " <font color=\"rgb(200,200,200)\">[" .. tostring(value) .. "]</font>"
    end

    if activeModules[name] then
        local data = activeModules[name]
        data.TextLabel.Text = displayText
        local w = data.TextLabel.TextBounds.X + 18
        TweenService:Create(data.Holder, TweenInfo.new(0.25), {
            Size = UDim2.new(0, w, 0, 24)
        }):Play()
        return
    end

    local holder, frame, text, sidebar = CreateModuleLabel(name)
    holder.Parent = ListContainer
    text.Text = displayText

    local width = text.TextBounds.X + 18
    holder.Size = UDim2.new(0, width, 0, 24)

    activeModules[name] = {
        Holder = holder,
        Frame = frame,
        TextLabel = text,
        SideBar = sidebar
    }

    UpdateList()

    if arrayEnabled then
        SlideIn(frame)
    end
end

local function AddToArrayList(name, value)
    enabledFeatures[name] = {Value = value}
    if arrayEnabled then
        RenderFeatureModule(name, value)
    end
end

local function RemoveFromArrayList(name)
    enabledFeatures[name] = nil
    local data = activeModules[name]
    if data then
        SlideOut(data.Frame)
        task.delay(0.45, function()
            if data.Holder then data.Holder:Destroy() end
        end)
        activeModules[name] = nil
    end
end

RunService.RenderStepped:Connect(function()
    local c = Color3.fromHSV((os.clock() * 0.2) % 1, 0.75, 1)
    TitleLabel.TextColor3 = c
    for _, data in pairs(activeModules) do
        data.TextLabel.TextColor3 = c
        data.SideBar.BackgroundColor3 = c
    end
end)

