Tab:Toggle({
    Flag = "Beautiful 1",
    Title = "显示开启功能信息",
    Value = false,
    Callback = function(state)
        arrayEnabled = state

        if state then
            ScreenGui.Enabled = true

            TweenService:Create(TitleLabel, TweenInfo.new(0.6, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                Position = UDim2.new(1, -210, 0, 0)
            }):Play()

            for name, info in pairs(enabledFeatures) do
                RenderFeatureModule(name, info.Value)
            end
        else
            TweenService:Create(TitleLabel, TweenInfo.new(0.4, Enum.EasingStyle.Quart, Enum.EasingDirection.In), {
                Position = UDim2.new(1, 50, 0, 0)
            }):Play()

            for _, data in pairs(activeModules) do
                SlideOut(data.Frame)
            end

            task.delay(0.5, function()
                if not arrayEnabled then
                    for k, v in pairs(activeModules) do
                        if v.Holder then v.Holder:Destroy() end
                        activeModules[k] = nil
                    end
                    ScreenGui.Enabled = false
                end
            end)
        end
    end
})

