local G = {}

G.Players = game:GetService("Players")
G.RS = game:GetService("ReplicatedStorage")
G.RunService = game:GetService("RunService")
G.localPlayer = G.Players.LocalPlayer
G.IgnoreDeadPlayers = false
G.GlobalAttackRange = 100
G.TargetPlayerName = "Nearest"
G.lastDash = 0
G.KillAuraConfig = { DashInterval = 0.7 }
G.abilitySpamEnabled = false
G.abilitySpamSelected = "全部"
G.abilitySpamSpeed = 0.05
G.abilityIsTransformed = false
G.task_wait = task.wait
G.task_spawn = task.spawn
G.math_random = math.random
G.tick_ = tick

G.remoteAbility = G.RS:WaitForChild("Remotes"):WaitForChild("Abilities"):WaitForChild("Ability")
G.remoteCombatAction = G.RS:WaitForChild("Remotes"):WaitForChild("Combat"):WaitForChild("Action")
G.remoteCombatProjectile = G.RS:WaitForChild("Remotes"):WaitForChild("Combat"):WaitForChild("Projectile")
G.remoteDashAbility = G.RS:WaitForChild("Remotes"):WaitForChild("Character"):WaitForChild("DashAbility")
G.remoteAbilityCanceled = G.RS:WaitForChild("Remotes"):WaitForChild("Abilities"):WaitForChild("AbilityCanceled")

pcall(function()
    G.abilityIsTransformed = G.localPlayer.Info.Transform.Value or false
    G.localPlayer.Info.Transform:GetPropertyChangedSignal("Value"):Connect(function()
        G.abilityIsTransformed = G.localPlayer.Info.Transform.Value
    end)
end)

function G.triggerDash()
    if G.tick_() - G.lastDash < G.KillAuraConfig.DashInterval then return end
    G.lastDash = G.tick_()
    local hrp = G.localPlayer.Character and G.localPlayer.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local dashArgs = {[1]=hrp.CFrame,[2]="L",[3]=hrp.CFrame.LookVector,[5]=G.tick_()}
    local dashRemote = G.RS.Remotes.Character:FindFirstChild("Dash")
    if dashRemote then
        pcall(function() dashRemote:FireServer(unpack(dashArgs)) end)
    end
end

function G.GetCurrentCharacter()
    local success, result = pcall(function()
        return G.localPlayer.Data.Character.Value
    end)
    if success and result then return result end
    return "Unknown"
end

function G.FindNearestPlayer()
    local character = G.localPlayer.Character
    if not character then return nil end
    local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
    if not humanoidRootPart then return nil end
    local nearestPlayer = nil
    local shortestDistance = math.huge
    for _, player in ipairs(G.Players:GetPlayers()) do
        if player ~= G.localPlayer and player.Character then
            local targetRoot = player.Character:FindFirstChild("HumanoidRootPart")
            local targetHumanoid = player.Character:FindFirstChild("Humanoid")
            if targetRoot and targetHumanoid then
                if G.IgnoreDeadPlayers then
                    local health = targetHumanoid:GetAttribute("Health")
                    if not health or health <= 0 then continue end
                end
                local distance = (humanoidRootPart.Position - targetRoot.Position).Magnitude
                if distance < shortestDistance and distance < G.GlobalAttackRange then
                    shortestDistance = distance
                    nearestPlayer = player
                end
            end
        end
    end
    return nearestPlayer
end

function G.GetTargetPlayer()
    if G.TargetPlayerName and G.TargetPlayerName ~= "Nearest" then
        local targetPlayer = G.Players:FindFirstChild(G.TargetPlayerName)
        if targetPlayer and targetPlayer.Character then
            local targetRoot = targetPlayer.Character:FindFirstChild("HumanoidRootPart")
            local targetHumanoid = targetPlayer.Character:FindFirstChild("Humanoid")
            if targetRoot and targetHumanoid then
                if G.IgnoreDeadPlayers then
                    local health = targetHumanoid:GetAttribute("Health")
                    if health and health <= 0 then return nil end
                end
                return targetPlayer
            end
        end
        return nil
    end
    return G.FindNearestPlayer()
end

function G.getAbilityFolderName()
    return G.abilityIsTransformed and "Ultimates" or "Abilities"
end

function G.getAbilityPath(characterName, abilityNumber)
    local folderName = G.getAbilityFolderName()
    return G.RS:WaitForChild("Characters"):WaitForChild(characterName):WaitForChild(folderName):WaitForChild(tostring(abilityNumber))
end

function G.hasAbility(characterName, abilityNumber)
    local success, result = pcall(function()
        local charactersFolder = G.RS:WaitForChild("Characters")
        if not charactersFolder:FindFirstChild(characterName) then return false end
        local abilitiesFolder = charactersFolder[characterName]:FindFirstChild(G.getAbilityFolderName())
        if not abilitiesFolder then return false end
        if abilityNumber == "All" then
            return abilitiesFolder:FindFirstChild("1") and abilitiesFolder:FindFirstChild("2") and abilitiesFolder:FindFirstChild("3") and abilitiesFolder:FindFirstChild("4")
        end
        return abilitiesFolder:FindFirstChild(tostring(abilityNumber)) ~= nil
    end)
    return success and result
end

function G.getNearestCFrame()
    local nearest = G.GetTargetPlayer()
    if nearest and nearest.Character and nearest.Character:FindFirstChild("HumanoidRootPart") then
        return nearest.Character.HumanoidRootPart.CFrame
    end
    return CFrame.new(0, 0, 0)
end

function G.replaceAbilityString(str)
    if G.abilityIsTransformed then
        return string.gsub(str, "Abilities", "Ultimates")
    end
    return str
end

