local G = {}

G.Players = game:GetService("Players")
G.ReplicatedStorage = game:GetService("ReplicatedStorage")
G.LocalPlayer = G.Players.LocalPlayer

G.getChar = function()
    local ok, v = pcall(function() return G.LocalPlayer.Data.Character.Value end)
    return (ok and v) or nil
end

G.getWallCombo = function(charName)
    charName = charName or G.getChar()
    if not charName then return nil end
    local ch = G.ReplicatedStorage:FindFirstChild("Characters")
    if not ch then return nil end
    local cf = ch:FindFirstChild(charName)
    if not cf then return nil end
    return cf:FindFirstChild("WallCombo")
end

G.myHRP = function()
    local c = G.LocalPlayer.Character
    return c and c:FindFirstChild("HumanoidRootPart")
end

G.SelfGodmode = { enabled = false, thread = nil }

G.SelfGodmode._loop = function(self)
    while self.enabled do
        pcall(function()
            local char = G.LocalPlayer.Character
            if not char then return end
            local charName = G.getChar()
            if not charName then return end
            local wc = G.getWallCombo(charName)
            if not wc then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            local actionId = math.random(100000, 999999)
            local actionStr = "Action" .. math.random(1000, 9999)
            G.ReplicatedStorage.Remotes.Abilities.Ability:FireServer(wc, actionId)
            G.ReplicatedStorage.Remotes.Combat.Action:FireServer(
                wc,
                "Characters:" .. charName .. ":WallCombo",
                1,
                actionId,
                {
                    HitboxCFrames = { hrp.CFrame, hrp.CFrame },
                    BestHitCharacter = char,
                    HitCharacters = { char },
                    Ignore = {},
                    DeathInfo = {},
                    BlockedCharacters = {},
                    HitInfo = { IsFacing = true, GetUp = true, IsInFront = true, Blocked = false },
                    ServerTime = tick(),
                    Actions = {},
                    FromCFrame = hrp.CFrame
                },
                actionStr,
                0
            )
        end)
        task.wait(0.01)
    end
    self.thread = nil
end

G.SelfGodmode.Start = function(self)
    if self.enabled then return end
    self.enabled = true
    self.thread = task.spawn(function() self:_loop() end)
end

G.SelfGodmode.Stop = function(self)
    self.enabled = false
end

G.DummyGodmode = {
    enabled = false,
    thread = nil,
    targets = { "The Ultimate Bum", "Blocking Bum", "Attacking Bum" }
}

G.DummyGodmode._getBums = function(self)
    local list = {}
    local folder = workspace:FindFirstChild("Characters")
        and workspace.Characters:FindFirstChild("NPCs")
    if not folder then return list end
    for _, name in ipairs(self.targets) do
        local npc = folder:FindFirstChild(name)
        if npc and npc:FindFirstChild("HumanoidRootPart") then
            table.insert(list, npc)
        end
    end
    return list
end

G.DummyGodmode._loop = function(self)
    while self.enabled do
        pcall(function()
            local charName = G.getChar()
            if not charName then return end
            local wc = G.getWallCombo(charName)
            if not wc then return end
            local hrp = G.myHRP()
            if not hrp then return end
            for _, bum in ipairs(self:_getBums()) do
                local actionId = math.random(100000, 999999)
                G.ReplicatedStorage.Remotes.Abilities.Ability:FireServer(
                    wc, 33036, nil, bum, bum.HumanoidRootPart.Position
                )
                G.ReplicatedStorage.Remotes.Combat.Action:FireServer(
                    wc,
                    "Characters:" .. charName .. ":WallCombo",
                    1,
                    33036,
                    {
                        HitboxCFrames = {},
                        BestHitCharacter = bum,
                        HitCharacters = { bum },
                        Ignore = {},
                        DeathInfo = {},
                        Actions = {},
                        HitInfo = { IsFacing = true, IsInFront = true },
                        BlockedCharacters = {},
                        ServerTime = os.clock(),
                        FromCFrame = hrp.CFrame
                    },
                    "Action" .. math.random(1000, 9999),
                    0
                )
            end
        end)
        task.wait(0.1)
    end
    self.thread = nil
end

G.DummyGodmode.Start = function(self)
    if self.enabled then return end
    self.enabled = true
    self.thread = task.spawn(function() self:_loop() end)
end

G.DummyGodmode.Stop = function(self)
    self.enabled = false
end

G.AntiCounter = { enabled = false, thread = nil }

G.AntiCounter._loop = function(self)
    while self.enabled do
        pcall(function()
            local counterRemote = G.ReplicatedStorage:WaitForChild("Remotes")
                :WaitForChild("Combat"):FindFirstChild("Counter")
            if counterRemote then
                counterRemote:FireServer(true)
            end
        end)
        task.wait(0.05)
    end
    self.thread = nil
end

G.AntiCounter.Start = function(self)
    if self.enabled then return end
    self.enabled = true
    self.thread = task.spawn(function() self:_loop() end)
end

G.AntiCounter.Stop = function(self)
    self.enabled = false
end

G.InfiniteBlock = { enabled = false }

G.InfiniteBlock.Start = function(self)
    if self.enabled then return end
    self.enabled = true
    task.spawn(function()
        while self.enabled do
            pcall(function()
                G.ReplicatedStorage:WaitForChild("Remotes")
                    :WaitForChild("Combat")
                    :WaitForChild("Block"):FireServer(true)
            end)
            task.wait(1)
        end
    end)
end

G.InfiniteBlock.Stop = function(self)
    self.enabled = false
    pcall(function()
        G.ReplicatedStorage:WaitForChild("Remotes")
            :WaitForChild("Combat")
            :WaitForChild("Block"):FireServer(false)
    end)
end

G.GodmodeUltimate = { enabled = false }

G.GodmodeUltimate.Enable = function(self)
    if self.enabled then return end
    self.enabled = true
    G.SelfGodmode:Start()
    G.DummyGodmode:Start()
    G.AntiCounter:Start()
    G.InfiniteBlock:Start()
end

G.GodmodeUltimate.Disable = function(self)
    if not self.enabled then return end
    self.enabled = false
    G.SelfGodmode:Stop()
    G.DummyGodmode:Stop()
    G.AntiCounter:Stop()
