Vape.SaveConfig = function()
    local data = {
        X_Scale = Container.Position.X.Scale,
        X_Offset = Container.Position.X.Offset,
        Y_Scale = Container.Position.Y.Scale,
        Y_Offset = Container.Position.Y.Offset,
        Scale = Vape.Config.Scale,
        UseRainbow = Vape.Config.UseRainbow,
        Color = {Vape.Config.Color.R, Vape.Config.Color.G, Vape.Config.Color.B},
        Mode = Vape.Config.Mode
    }
    writefile(Vape.Config.File, Vape.Services.HttpService:JSONEncode(data))
end

Vape.LoadConfig = function()
    if isfile(Vape.Config.File) then
        local success, data = pcall(function() return Vape.Services.HttpService:JSONDecode(readfile(Vape.Config.File)) end)
        if success then
            Container.Position = UDim2.new(data.X_Scale or 0.75, data.X_Offset or -90, data.Y_Scale or 0.01, data.Y_Offset or 0)
            Vape.Config.Scale = data.Scale or 1
            Vape.Config.UseRainbow = data.UseRainbow
            Vape.Config.Color = Color3.new(data.Color[1], data.Color[2], data.Color[3])
            Vape.Config.Mode = data.Mode or "展示在屏幕"
        end
    else
        Container.Position = UDim2.new(0.75, -90, 0.01, 0)
    end
end

Vape.LoadConfig()

Vape.MakeDraggable = function(frame)
    local dragging, dragInput, dragStart, startPos
    frame.Active = true
    frame.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = Container.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                    Vape.SaveConfig()
                end
            end)
        end
    end)
    frame.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            dragInput = input
        end
    end)
    Vape.Services.UserInputService.InputChanged:Connect(function(input)
        if input == dragInput and dragging then
            local delta = input.Position - dragStart
            Container.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)
end

Vape.CreatePlayerHUD = function(targetPlayer, isDummy)
    local HUD = {Billboard = nil}
    local MainFrame = Instance.new("Frame")
    MainFrame.Size = UDim2.new(0, 150 * Vape.Config.Scale, 0, 45 * Vape.Config.Scale)
    MainFrame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    MainFrame.BackgroundTransparency = 1
    MainFrame.BorderSizePixel = 0

    local isHeadMode = (not isDummy and Vape.Config.Mode == "展示在头部右边")

    if isDummy or not isHeadMode then
        MainFrame.Parent = Container
    else
        local Billboard = Instance.new("BillboardGui")
        Billboard.Name = "HeadHUD"
        Billboard.Size = UDim2.new(0, 150 * Vape.Config.Scale, 0, 45 * Vape.Config.Scale)
        Billboard.Adornee = targetPlayer.Character:FindFirstChild("Head") or targetPlayer.Character:FindFirstChild("HumanoidRootPart")
        Billboard.StudsOffset = Vector3.new(0, 2.5 * Vape.Config.Scale, 0)
        Billboard.AlwaysOnTop = true
        Billboard.Parent = ScreenGui
        MainFrame.Parent = Billboard
        HUD.Billboard = Billboard
    end

    local UICorner = Instance.new("UICorner")
    UICorner.CornerRadius = UDim.new(0, 4)
    UICorner.Parent = MainFrame

    local UIStroke = Instance.new("UIStroke")
    UIStroke.Thickness = 1.2 * Vape.Config.Scale
    UIStroke.Transparency = 1
    UIStroke.Parent = MainFrame

    local Avatar = Instance.new("ImageLabel")
    Avatar.Size = UDim2.new(0, 32 * Vape.Config.Scale, 0, 32 * Vape.Config.Scale)
    Avatar.Position = UDim2.new(0, 5 * Vape.Config.Scale, 0.5, -16 * Vape.Config.Scale)
    Avatar.BackgroundTransparency = 1
    Avatar.ImageTransparency = 1
    Avatar.Image = isDummy and "rbxthumb://type=AvatarHeadShot&id="..LP.UserId.."&w=100&h=100" or "rbxthumb://type=AvatarHeadShot&id=" .. targetPlayer.UserId .. "&w=100&h=100"
    Avatar.Parent = MainFrame

    local Info = Instance.new("Frame")
    Info.Size = UDim2.new(1, -45 * Vape.Config.Scale, 1, -6 * Vape.Config.Scale)
    Info.Position = UDim2.new(0, 42 * Vape.Config.Scale, 0, 3 * Vape.Config.Scale)
    Info.BackgroundTransparency = 1
    Info.Parent = MainFrame

    local DName = Instance.new("TextLabel")
    DName.Size = UDim2.new(1, 0, 0, 12 * Vape.Config.Scale)
    DName.Font = Enum.Font.GothamBold
    DName.TextSize = 10 * Vape.Config.Scale
    DName.Text = isDummy and "Example Name" or targetPlayer.DisplayName
    DName.TextXAlignment = Enum.TextXAlignment.Left
    DName.BackgroundTransparency = 1
    DName.TextTransparency = 1
    DName.Parent = Info

    local UName = Instance.new("TextLabel")
    UName.Size = UDim2.new(1, 0, 0, 10 * Vape.Config.Scale)
    UName.Position = UDim2.new(0, 0, 0, 12 * Vape.Config.Scale)
    UName.Font = Enum.Font.Gotham
    UName.TextSize = 8 * Vape.Config.Scale
    UName.Text = isDummy and "@Username" or "@" .. targetPlayer.Name
    UName.TextXAlignment = Enum.TextXAlignment.Left
    UName.BackgroundTransparency = 1
    UName.TextTransparency = 1
    UName.Parent = Info

    local HText = Instance.new("TextLabel")
    HText.Size = UDim2.new(1, 0, 0, 10 * Vape.Config.Scale)
    HText.Position = UDim2.new(0, 0, 0, 22 * Vape.Config.Scale)
    HText.Font = Enum.Font.GothamMedium
    HText.TextSize = 8 * Vape.Config.Scale
    HText.TextXAlignment = Enum.TextXAlignment.Left
    HText.BackgroundTransparency = 1
    HText.TextTransparency = 1
    HText.Parent = Info

    local HBack = Instance.new("Frame")
    HBack.Size = UDim2.new(0.95, 0, 0, 6 * Vape.Config.Scale)
    HBack.Position = UDim2.new(0, 0, 1, -6 * Vape.Config.Scale)
    HBack.BackgroundColor3 = Color3.fromRGB(230, 230, 230)
    HBack.BackgroundTransparency = 1
    HBack.BorderSizePixel = 0
    HBack.Parent = Info
    Instance.new("UICorner", HBack).CornerRadius = UDim.new(1, 0)

    local HFill = Instance.new("Frame")
    HFill.Size = UDim2.new(isDummy and 1 or 0, 0, 1, 0)
    HFill.BackgroundTransparency = 1
    HFill.BorderSizePixel = 0
    HFill.Parent = HBack
    Instance.new("UICorner", HFill).CornerRadius = UDim.new(1, 0)

    function HUD:Show()
        local bgTransparency = isHeadMode and 1 or 0.4
        Vape.Services.TweenService:Create(MainFrame, TweenInfo.new(1.0), {BackgroundTransparency = bgTransparency}):Play()
        Vape.Services.TweenService:Create(UIStroke, TweenInfo.new(1.0), {Transparency = 0.5}):Play()
        Vape.Services.TweenService:Create(Avatar, TweenInfo.new(1.0), {ImageTransparency = 0}):Play()
        Vape.Services.TweenService:Create(DName, TweenInfo.new(1.0), {TextTransparency = 0}):Play()
        Vape.Services.TweenService:Create(UName, TweenInfo.new(1.0), {TextTransparency = 0.1}):Play()
        Vape.Services.TweenService:Create(HText, TweenInfo.new(1.0), {TextTransparency = 0}):Play()
        Vape.Services.TweenService:Create(HBack, TweenInfo.new(1.0), {BackgroundTransparency = 0.6}):Play()
        Vape.Services.TweenService:Create(HFill, TweenInfo.new(1.0), {BackgroundTransparency = 0}):Play()
    end

    function HUD:Hide()
        local t = Vape.Services.TweenService:Create(MainFrame, TweenInfo.new(0.8), {BackgroundTransparency = 1})
        Vape.Services.TweenService:Create(UIStroke, TweenInfo.new(0.8), {Transparency = 1}):Play()
        Vape.Services.TweenService:Create(Avatar, TweenInfo.new(0.8), {ImageTransparency = 1}):Play()
        Vape.Services.TweenService:Create(DName, TweenInfo.new(0.8), {TextTransparency = 1}):Play()
        Vape.Services.TweenService:Create(UName, TweenInfo.new(0.8), {TextTransparency = 1}):Play()
        Vape.Services.TweenService:Create(HText, TweenInfo.new(0.8), {TextTransparency = 1}):Play()
        Vape.Services.TweenService:Create(HBack, TweenInfo.new(0.8), {BackgroundTransparency = 1}):Play()
        Vape.Services.TweenService:Create(HFill, TweenInfo.new(0.8), {BackgroundTransparency = 1}):Play()
        t:Play()
        t.Completed:Connect(function() 
            if HUD.Billboard then HUD.Billboard:Destroy() end
            MainFrame:Destroy() 
        end)
    end

    function HUD:Update(hum)
        local health = hum and hum.Health or 100
        local maxHealth = hum and hum.MaxHealth or 100
        HText.Text = string.format("%.1f HP", health)
        local color = Color3.fromRGB(0, 255, 0)
        if health < 30 then color = Color3.fromRGB(255, 0, 0) elseif health <= 50 then color = Color3.fromRGB(255, 165, 0) end
        Vape.Services.TweenService:Create(HFill, TweenInfo.new(0.3), {Size = UDim2.new(health/maxHealth, 0, 1, 0), BackgroundColor3 = color}):Play()
        local displayColor = Vape.Config.UseRainbow and Color3.fromHSV((tick() * 0.3) % 1, 0.7, 1) or Vape.Config.Color
        UIStroke.Color = displayColor
        DName.TextColor3 = displayColor
        UName.TextColor3 = displayColor
        HText.TextColor3 = displayColor
    end

    if isDummy then Vape.MakeDraggable(MainFrame) end
    return HUD
end

Vape.Services.RunService.RenderStepped:Connect(function()
    if Vape.Config.CustomPos and Vape.Config.DummyHUD then
        Vape.Config.DummyHUD:Update()
        for id, d in pairs(Vape.Config.ActiveHUDs) do d.hud:Hide() Vape.Config.ActiveHUDs[id] = nil end
        return
    end
    if not Vape.Config.Enabled then
        for id, d in pairs(Vape.Config.ActiveHUDs) do d.hud:Hide() Vape.Config.ActiveHUDs[id] = nil end
        return
    end
    local nearby = {}
    for _, p in pairs(Vape.Services.Players:GetPlayers()) do
        if p ~= LP and p.Character and p.Character:FindFirstChild("Humanoid") and p.Character:FindFirstChild("HumanoidRootPart") then
            local hum = p.Character.Humanoid
            if LP:DistanceFromCharacter(p.Character.HumanoidRootPart.Position) <= 100 and hum.Health > 0 then
                nearby[p.UserId] = {p = p, h = hum}
            end
        end
    end
    for id, d in pairs(Vape.Config.ActiveHUDs) do
        if not nearby[id] then d.hud:Hide() Vape.Config.ActiveHUDs[id] = nil
        else d.hud:Update(nearby[id].h) end
    end
    for id, d in pairs(nearby) do
        if not Vape.Config.ActiveHUDs[id] then
            local n = Vape.CreatePlayerHUD(d.p, false)
            Vape.Config.ActiveHUDs[id] = {hud = n}
            n:Show()
        end
    end
end)

Vape.ApplyForceField = function()
    local Char = LP.Character
    if not Char then return end
    for _, part in pairs(Char:GetDescendants()) do
        if part:IsA("BasePart") then
            if not Vape.Material.Original[part] then
                Vape.Material.Original[part] = part.Material
            end
            part.Material = Enum.Material.ForceField
            part.Color = Vape.Material.Color
        end
    end
end

Vape.RestoreMaterial = function()
    for part, mat in pairs(Vape.Material.Original) do
        if part and part.Parent then
            part.Material = mat
        end
    end
    table.clear(Vape.Material.Original)
end

