local function isNight()
    local gameStuff = workspace:FindFirstChild("GameStuff")
    if not gameStuff then return false end
    local valuesFolder = gameStuff:FindFirstChild("Values")
    if not valuesFolder then return false end
    return valuesFolder:GetAttribute("Night") == true
end

