TabHandles.plant:Section({ 
	Title = "种植树",
	Desc = "种植",
	Icon = 'tree-pine',
	ImageSize = 30,
	Opened = true,
})

local plantShape = "圆形" 
local radius = 40
local spacing = 1
local Root = "玩家"
local isPlanting = false

TabHandles.plant:Dropdown({ 
	Title = "选择种植形状",
	Desc = '形状',
	Values = {"圆形", "正方形"}, 
	Value = "圆形", 
	Callback = function(value) 
		plantShape = value 
	end 
})

