TabHandles.Auto3:Input({
	Title = "饥饿设置",
	Desc = "当饥饿达到多少时进食",
	Value = tostring(hungerThreshold),
	Placeholder = "75",
	Numeric = true,
	Callback = function(value)
		local n = tonumber(value)
		if n then
			hungerThreshold = math.clamp(n, 0, 100)
		end
	end
})

local autoFeed

