	Title = "自动进食",
	Value = false,
	Callback = function(state)
		autoFeed = state
		if state then
			task.spawn(function()
				while autoFeed do
					task.wait(0.075)
					if wiki(Food) == 0 then
						autoFeed = false
						notifeed(Food)
						break
					end
					if ghn() <= hungerThreshold then
						feed(Food)
					end
				end
			end)
		end
	end
})

