                        for _, part in pairs(cameraArms:GetDescendants()) do
                            if part:IsA("MeshPart") then
                                part.Material = Enum.Material[gunMaterial]
                                part.Color = gunColor
                            end
                        end
                    end
                end
            end)
        end
    end
})
