                                            if gui:IsA("ImageLabel") and gui.Parent and 
                                               gui.Parent.Parent.Parent.Name == "CustomerSpeechUI" and
                                               gui.Parent.Parent.Size == UDim2.new(1, 0, 1, 0) then
                                               ReplicatedStorage.Events.Restaurant.TaskCompleted:FireServer({
