TabHandles.Auto3:Input({
	Title = "hunger threshold",
	Desc = "eat when hunger is below this",
	Value = tostring(hungerThreshold),
	Placeholder = "75",
	Numeric = true,
	Callback = function(value)
		local n = tonumber(value)
		if n then
			hungerThreshold = math.clamp(n, 0, 100)
		end
	end
})

local autoFeed

TabHandles.Auto3:Toggle({
	Title = "auto feed",
	Value = false,
	Callback = function(state)
		autoFeed = state
		if state then
			task.spawn(function()
				while autoFeed do
					task.wait(0.075)
					if wiki(Food) == 0 then
						autoFeed = false
						notifeed(Food)
						break
					end
					if ghn() <= hungerThreshold then
						feed(Food)
					end
				end
			end)
		end
	end
})

TabHandles.Auto4:Section({ 
	Title = "fishing",
	Desc = "automatic",
	Icon = 'fish',
	ImageSize = 30,
	Opened = true,
})

Main:Toggle({
    Title = "auto fishing",
    Value = false,
    Callback = function(value)
        autoFishingEnabled = value
        if value then
            spawn(function()
                local Players = game:GetService("Players")
                local RunService = game:GetService("RunService")
                local player = Players.LocalPlayer
                local playerGui = player:WaitForChild("PlayerGui")
                
                task.wait(1)
                
                local fishingCatchFrame = playerGui.Interface.FishingCatchFrame
                local timingBar = fishingCatchFrame.TimingBar
                local successArea = timingBar.SuccessArea
                local bar = timingBar.Bar
                local button = playerGui.MobileButtons.Frame.Button3
                local canClick = true
                
                local function checkOverlap(f1, f2)
                    local p1 = f1.AbsolutePosition
                    local s1 = f1.AbsoluteSize
                    local p2 = f2.AbsolutePosition
                    local s2 = f2.AbsoluteSize
                    
                    return not (
                        p1.X + s1.X < p2.X or
                        p2.X + s2.X < p1.X or
                        p1.Y + s1.Y < p2.Y or
                        p2.Y + s2.Y < p1.Y
                    )
                end
                
                local function clickButton()
                    for _, connection in pairs(getconnections(button.MouseButton1Down)) do
                        connection:Fire()
                    end
                end
                
                while autoFishingEnabled do
                    if fishingCatchFrame.Visible and timingBar.Visible then
                        if checkOverlap(successArea, bar) and canClick then
                            canClick = false
                            clickButton()
                            task.wait(0.1)
                            canClick = true
                        end
                    else
                        canClick = true
                    end
                    wait(0)
                end
            end)
        end
