local mt = getrawmetatable(game)
local old = mt.__namecall
local enabled = false

local function hook(state)
    setreadonly(mt, false)
    if state then
        mt.__namecall = newcclosure(function(self, ...)
            local method = getnamecallmethod()
            local args = {...}

            if method == "FireServer" then
                if tostring(self) == "Ability" then
                    if #args > 0 then
                        local abilityName = args[1]
                        if abilityName and abilityName.Name == "WallCombo" then
                            return nil
                        end
                    end
                elseif tostring(self) == "Action" then
                    if #args > 0 then
                        local abilityData = args[1]
                        if abilityData and type(abilityData) == "table" then
                            local abilityName = abilityData[2]
                            if abilityName and abilityName:find("WallCombo") then
                                return nil
                            end
                        end
                    end
                end
            end

            return old(self, ...)
        end)
    else
        mt.__namecall = old
    end
    setreadonly(mt, true)
end

