G.saiyanFireGon = function(abilityNum)
    local lp = G.LocalPlayer
    local char = lp.Character
    if not char then return end
    local hrp = G.getHRP()
    if not hrp then return end
    local targets = {}
    for _, p in ipairs(G.Players:GetPlayers()) do
        if p ~= lp and p.Character then
            local th = p.Character:FindFirstChild("Humanoid")
            if th and th.Health > 0 then
                table.insert(targets, p.Character)
            end
        end
    end
    if #targets == 0 then return end
    for _, targetChar in ipairs(targets) do
        local targetHRP = targetChar:FindFirstChild("HumanoidRootPart")
        if not targetHRP then continue end
        local jitterCF = targetHRP.CFrame * CFrame.new(
            math.random(-300, 300),
            math.random(-30, 30),
            math.random(-300, 300)
        )
        local actionID = math.random(100000, 9999999)
        local actionNumber = "Action"..math.random(1000, 9999)
        pcall(function()
            local ability = G.ReplicatedStorage.Characters["Gon"].Abilities[abilityNum]
            if not ability then return end
            G.ReplicatedStorage.Remotes.Abilities.Ability:FireServer(ability, actionID)
            G.ReplicatedStorage.Remotes.Combat.Action:FireServer(
                ability, "Gon:Abilities:"..abilityNum, 1, actionID,
                {
                    HitboxCFrames = {jitterCF},
                    BestHitCharacter = targetChar,
                    HitCharacters = {targetChar},
                    Ignore = {[actionNumber] = {targetChar}},
                    DeathInfo = {},
                    Actions = {[actionNumber] = {}},
                    HitInfo = {Blocked = false, IsFacing = true, IsInFront = true},
                    BlockedCharacters = {},
                    ServerTime = tick(),
                    FromCFrame = jitterCF
                },
                actionNumber
            )
            task.wait(0.1)
            pcall(function()
                G.ReplicatedStorage.Remotes.Abilities.AbilityCanceled:FireServer(ability)
            end)
        end)
    end
end

G.pullAllPlayers = function()
    local lp = G.LocalPlayer
    local char = lp.Character
    if not char then return end
    local targets = {}
    for _, p in ipairs(G.Players:GetPlayers()) do
        if p ~= lp and p.Character then
            local th = p.Character:FindFirstChild("Humanoid")
            if th and th.Health > 0 then
                table.insert(targets, p.Character)
            end
        end
    end
    if #targets == 0 then return end
    for _, targetChar in ipairs(targets) do
        task.spawn(function()
            G.saiyanFireGon("1")
            task.wait(0.05)
            G.saiyanFireGon("2")
        end)
    end
end

G.autoSpin = function()
    local char = G.LocalPlayer.Character
    local hrp = G.getHRP()
    local hum = char and char:FindFirstChild("Humanoid")
    if hrp and hum then
        pcall(function()
            hum.AutoRotate = false
            hrp.CFrame = hrp.CFrame * CFrame.Angles(0, math.rad(G.cfg.SpinSpeed), 0)
        end)
    end
end

G.ActionRemote = G.ReplicatedStorage:FindFirstChild("Remotes")
if G.ActionRemote then
    G.ActionRemote = G.ActionRemote:FindFirstChild("Combat")
    if G.ActionRemote then
        G.ActionRemote = G.ActionRemote:FindFirstChild("Action")
    end
end

if G.ActionRemote then
    local oldNamecall
    oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)
        local args = {...}
        local method = getnamecallmethod()
        if self == G.ActionRemote and method == "FireServer" and G.cfg.Enabled then
            for _, arg in pairs(args) do
                if type(arg) == "table" and arg.HitCharacters then
                    local newTargets = {}
                    for _, ch in pairs(arg.HitCharacters) do
                        for i = 1, G.cfg.DamageMultiplier do
                            table.insert(newTargets, ch)
                        end
                    end
                    arg.HitCharacters = newTargets
                end
            end
        end
        return oldNamecall(self, unpack(args))
    end)
end

