        G.auraConnection = G.RunService.Heartbeat:Connect(function()
            local hrp = G.getHRP()
            if not hrp then return end
            for _, scrapChild in ipairs(G.ScrapFolder:GetChildren()) do
                if G.isAvailable(scrapChild) then
