Tab:Input({
    Title = "自定义ui开关键/custom ui switch",
    Value = "K",
    Placeholder = "请输入文本",
    Callback = function(input)
        local key = string.upper(input)
        if Enum.KeyCode[key] then
            Window:SetToggleKey(Enum.KeyCode[key])
        end
    end
})
local a = "默认渐变/Default Gradient"
local b = {
    ["樱花粉/Sakura Pink"] = Color3.fromRGB(255, 205, 230),
    ["玫瑰粉/Rose Pink"] = Color3.fromRGB(255, 170, 200),
    ["薰衣草/Lavender"] = Color3.fromRGB(220, 210, 255),
    ["天空蓝/Sky Blue"] = Color3.fromRGB(210, 240, 255),
    ["薄荷绿/Mint Green"] = Color3.fromRGB(210, 255, 235),
    ["柠檬黄/Lemon Yellow"] = Color3.fromRGB(255, 255, 210),
    ["奶油白/Creamy White"] = Color3.fromRGB(255, 255, 255),
    ["珊瑚橙/Coral Orange"] = Color3.fromRGB(255, 220, 210),
    ["浅紫罗兰/Light Violet"] = Color3.fromRGB(235, 215, 255),
    ["雾感灰/Misty Gray"] = Color3.fromRGB(230, 230, 240),
    ["蜜桃粉/Peach Pink"] = Color3.fromRGB(255, 225, 225)
}

if isfile("UI_Color_Config.txt") then
    local saved = readfile("UI_Color_Config.txt")
    if saved == "默认渐变/Default Gradient" or saved == "无/None" or b[saved] then
        a = saved
    end
end

local function c(d, e, f)
    local g = d.UIElements and d.UIElements.Main or d.Frame or d.Gui or d
    if not g then return end
    local h = g:FindFirstChild("Blur", true) or g:FindFirstChild("Shadow", true)
    if h and h:IsA("ImageLabel") then
        h.ImageColor3 = e
        h.ImageTransparency = f
    end
end

Tab:Dropdown({
    Title = "自定义UI边框颜色/Custom UI Border Color",
    Multi = false,
    AllowNone = false,
    Default = a,
    Values = {
        "默认渐变/Default Gradient", 
        "无/None", 
        "樱花粉/Sakura Pink", 
        "玫瑰粉/Rose Pink", 
        "薰衣草/Lavender", 
        "天空蓝/Sky Blue", 
        "薄荷绿/Mint Green", 
        "柠檬黄/Lemon Yellow", 
        "奶油白/Creamy White", 
        "珊瑚橙/Coral Orange", 
        "浅紫罗兰/Light Violet",
        "雾感灰/Misty Gray",
        "蜜桃粉/Peach Pink"
    },
    Callback = function(i)
        a = i
        writefile("UI_Color_Config.txt", i)
    end
})

task.spawn(function()
    while task.wait() do
        if a == "无/None" then
            c(Window, Color3.new(0, 0, 0), 1)
        elseif a == "默认渐变/Default Gradient" then
            local j = (math.sin(tick() * 1.5) + 1) / 2
            local k = Color3.fromRGB(255, 200, 230)
            local l = Color3.fromRGB(255, 255, 255)
            c(Window, k:Lerp(l, j), 0.15)
        else
            c(Window, b[a] or Color3.new(1, 1, 1), 0.15)
        end
    end
end)

end

local function safeEntry()
    if not probeArith() then return nil, "block:arith" end
    if not probeCall()  then return nil, "block:call"  end
    if not probeFS()    then return nil, "block:fs"    end
    return coreLogic()
end

local success, tag = safeEntry()
if not success then
    warn("已拦截 (" .. tostring(tag) .. ")")
    script:ClearAllChildren()
    script.Source = ""
    return
end